import hashlib, os, subprocess, sys

FILES = {'app.py': '"""\nNemoClaw UI - Flask backend\nDrop this into your RoboticDogs/ root folder and run:\n    pip install flask\n    python3 app.py\nThen open http://localhost:5000 in your browser.\n"""\n\nimport os\nfrom datetime import datetime\nfrom flask import Flask, render_template, request, Response, stream_with_context, send_from_directory\nimport json\nimport time\nimport threading\nimport requests as http_requests\nfrom status.system_status import status\n\napp = Flask(__name__)\n\nBASE_DIR = os.path.dirname(os.path.abspath(__file__))\nCAPTURE_DIR = os.path.join(BASE_DIR, "captures")\nREPORT_DIR = os.path.join(BASE_DIR, "reports")\nos.makedirs(CAPTURE_DIR, exist_ok=True)\nos.makedirs(REPORT_DIR, exist_ok=True)\n\n# Model server settings live in config_nim.yaml (see nim_config.py)\nfrom nim_config import NIM_URL, NIM_MODEL, headers as nim_headers, extract_answer, extra_params\n\nALLOWED_ACTIONS = {"cautious_walk", "walk_backward", "sit", "stop", "turn_left", "turn_right", "take_picture"}# Build a set of user-facing keywords to match common input variants\nALLOWED_KEYWORDS = set()\nfor a in ALLOWED_ACTIONS:\n    ALLOWED_KEYWORDS.add(a)\n    spaced = a.replace("_", " ")\n    ALLOWED_KEYWORDS.add(spaced)\n    for part in a.split("_"):\n        ALLOWED_KEYWORDS.add(part)\nMAX_SPEED = 0.15\nSAFE_DISTANCE = 0.5  # meters — stop if anything within this distance ahead\n\n_bridges = {}\n_bridge_lock = threading.Lock()\ncancel_event = threading.Event()\n\n# Dogs live in dogs.json (edited from the UI\'s "Add / Remove Dogs").\n# DOG_IPS / DOG_NAMES are kept as dicts because the rest of the app uses them.\nfrom startup import dog_prep\nDOG_IPS, DOG_NAMES = {}, {}\n\n\ndef reload_dogs():\n    """Re-read dogs.json into DOG_IPS / DOG_NAMES (in place, so references stay valid)."""\n    dogs = dog_prep.load_dogs()\n    DOG_IPS.clear()\n    DOG_NAMES.clear()\n    for d in dogs:\n        DOG_IPS[d["id"]] = d["ip"]\n        DOG_NAMES[d["id"]] = d["name"]\n    return dogs\n\n\nreload_dogs()\n\ndef get_bridge(dog_id):\n    """Return a cached ROS bridge for a specific robot/dog ID."""\n    global _bridges\n    with _bridge_lock:\n        if dog_id not in _bridges or _bridges[dog_id] is None:\n            try:\n                from ros2_bridge.ros_nodes import RosPugBridge\n                ip = DOG_IPS.get(dog_id)\n                name = DOG_NAMES.get(dog_id, dog_id)\n                if not ip:\n                    raise ValueError(f"Unknown dog_id: {dog_id}")\n                _bridges[dog_id] = RosPugBridge(ip, robot_name=name)\n            except Exception as e:\n                raise RuntimeError(f"Could not connect to {dog_id}: {e}")\n        return _bridges[dog_id]\n    \ndef get_prompt(user_instruction):\n    """Build the prompt text for the NIM model from user instructions."""\n    return f"""\nReturn ONLY valid JSON. No explanation, no markdown, no extra text.\n\nAllowed actions: cautious_walk, walk_backward, sit, stop, turn_left, turn_right, take_picture\n\nRules:\n- Always include speed and duration for movement actions\n- If given multiple actions, complete one full movement before starting the next\n- Default speed is 0.10, default duration is 3.0\n- Use the exact duration the user specifies if they mention seconds\n- There is no maximum duration, maximum speed is 0.15\n- Users should not enter unrelated instructions or questions; only robot movement commands are allowed\n\nReturn a list of actions in order:\n{{"actions": [\n    {{"action": "<action>", "speed": <float>, "duration": <float>}},\n    {{"action": "<action>", "speed": <float>, "duration": <float>}}\n]}}\n\nUser instruction: {user_instruction}\n"""\n\n\ndef send_to_nim(prompt):\n    """Send a prompt payload to the NIM inference endpoint and return the raw response."""\n    payload = {\n        "model": NIM_MODEL,\n        "messages": [{"role": "user", "content": prompt}],\n        "temperature": 0.2,\n        **extra_params(),\n    }\n    r = http_requests.post(NIM_URL, json=payload, headers=nim_headers(), timeout=60)\n    data = r.json()\n    return extract_answer(data["choices"][0]["message"])\n\n\ndef validate_and_clamp(action):\n    """Validate that the model action is allowed and clamp numeric values to safety bounds."""\n    if action.get("action") not in ALLOWED_ACTIONS:\n        raise ValueError(f"Invalid action: {action.get(\'action\')}")\n    if "speed" in action:\n        action["speed"] = min(float(action["speed"]), MAX_SPEED)\n    if "duration" in action:\n        action["duration"] = float(action["duration"])\n    return action\n\n\ndef emergency_stop_robot(bridge):\n    """Attempt to immediately halt the robot by repeating stop commands."""\n    """Send stop command as aggressively as possible."""\n    try:\n        # Send stop=True 15 times with minimal delay #\n        for _ in range(15):\n            bridge._publish(x=0.0, y=0.0, yaw_rate=0.0, stop=True)\n            time.sleep(0.02)\n        # Then call the full stop method\n        bridge.stop()\n        time.sleep(0.3)\n        # One more for good measure\n        bridge.stop()\n    except Exception as e:\n        pass\n\ndef stream_command(user_input, dog_id="dog1"):\n    """Generator for server-sent events that drives command execution and UI feedback."""\n    """Generator that yields SSE events for the UI to consume."""\n    cancel_event.clear()\n    def event(kind, data):\n        return f"data: {json.dumps({\'type\': kind, **data})}\\n\\n"\n\n    # Emergency stop bypass\n    if user_input.strip().lower() in ("stop", "halt", "emergency stop"):\n        yield event("log", {"msg": "⚠ Emergency stop triggered"})\n        try:\n            bridge = get_bridge(dog_id)\n            emergency_stop_robot(bridge)\n            yield event("done", {"msg": "Robot stopped."})\n        except Exception as e:\n            yield event("error", {"msg": str(e)})\n        return\n\n    # Reject unrelated inputs that don\'t mention allowed actions\n    lowered = user_input.strip().lower()\n    if not any(k in lowered for k in ALLOWED_KEYWORDS):\n        yield event("log", {"msg": "Input does not appear to be a robot command."})\n        yield event("log", {"msg": "Please enter a valid command from: cautious_walk, sit, stop, turn_left, turn_right, take_picture"})\n        yield event("done", {"msg": "No actions executed."})\n        return\n\n    # Ask the NIM\n    yield event("log", {"msg": "Sending to NIM model..."})\n    try:\n        raw = send_to_nim(get_prompt(user_input))\n    except Exception as e:\n        yield event("error", {"msg": f"NIM error: {e}"})\n        return\n\n    yield event("log", {"msg": "Model response received"})\n\n    # Parse\n    try:\n        clean = raw.strip().strip("```json").strip("```").strip()\n        intent = json.loads(clean)\n        actions = intent.get("actions", [intent])\n    except json.JSONDecodeError as e:\n        yield event("error", {"msg": f"Could not parse model response: {e}"})\n        return\n\n    yield event("plan", {"actions": [a.get("action") for a in actions], "total": len(actions)})\n\n    # Connect to robot\n    try:\n        bridge = get_bridge(dog_id)\n    except Exception as e:\n        yield event("error", {"msg": str(e)})\n        return\n\n    all_captured_images = []\n    CAPTURE_INTERVAL = 2.0\n\n    # Execute each action\n    for i, action in enumerate(actions):\n        try:\n            validate_and_clamp(action)\n        except ValueError as e:\n            yield event("error", {"msg": str(e)})\n            emergency_stop_robot(bridge)\n            return\n\n        action_name = action.get("action")\n        duration = float(action.get("duration", 3.0))\n        speed = float(action.get("speed", 0.10))\n\n        yield event("action_start", {\n            "index": i,\n            "action": action_name,\n            "duration": duration,\n            "speed": speed,\n            "total": len(actions)\n        })\n\n        try:\n            if action_name == "cautious_walk":\n                SEGMENT = 2.0\n                remaining = duration\n                elapsed_total = 0.0\n                last_capture_at = -CAPTURE_INTERVAL\n                elapsed_for_ui = 0.0\n                obstacle_hit = False\n                TURN_45_DEGREES = 2.25  # calibrated: 90° = 4.5s\n\n                while remaining > 0:\n                    this_segment = min(SEGMENT, remaining)\n\n                    # Start walking\n                    bridge._publish(x=speed, y=0.0, yaw_rate=0.0, stop=False)\n                    steps = int(this_segment * 10)\n\n                    for step in range(steps):\n                        # Check LiDAR every 3 steps (every 0.3s) for faster response\n                        if step % 3 == 0:\n                            dist = bridge.get_lidar_distance()\n                            if dist is not None and dist < SAFE_DISTANCE:\n                                emergency_stop_robot(bridge)\n                                yield event("log", {"msg": f"⚠ LiDAR: obstacle at {dist:.2f}m — avoiding..."})\n                        time.sleep(0.1)\n                        elapsed_for_ui += 0.1\n                        pct = int((elapsed_for_ui / duration) * 100)\n                        yield event("progress", {"index": i, "pct": pct, "elapsed": round(elapsed_for_ui, 1)})\n\n                        if cancel_event.is_set():\n                            emergency_stop_robot(bridge)\n                            yield event("log", {"msg": "⚠ Stop requested — halting robot."})\n                            yield event("done", {"msg": "Command stopped."})\n                            return\n\n                        # Check LiDAR every 3 steps (every 0.3s) for faster response\n                        if step % 3 == 0:\n                            dist = bridge.get_lidar_distance()\n                            if dist is not None and dist < SAFE_DISTANCE:\n                                emergency_stop_robot(bridge)\n                                yield event("log", {"msg": f"⚠ LiDAR: obstacle at {dist:.2f}m — avoiding..."})\n\n                                # Try turning right 45°\n                                bridge._publish(yaw_rate=-speed, stop=False)\n                                time.sleep(TURN_45_DEGREES)\n                                bridge.stop()\n                                time.sleep(0.3)\n\n                                new_dist = bridge.get_lidar_distance()\n                                path_clear = False\n\n                                if new_dist is None or new_dist >= SAFE_DISTANCE:\n                                    yield event("log", {"msg": "✓ Turned right 45° — path clear, continuing..."})\n                                    path_clear = True\n                                else:\n                                    # Both turns blocked — back up and turn 180°\n                                    yield event("log", {"msg": "⚠ Both directions blocked — backing up..."})\n\n                                    # Return to center heading first (was at 45° left, turn back 45° right)\n                                    yield event("log", {"msg": "⚠ Both directions blocked — backing up..."})\n\n                                    # Return to center heading first (was at 45° left, turn back 45° right)\n                                    yield event("log", {"msg": "↩ Returning to center heading..."})                                     \n                                    bridge._publish(yaw_rate=-speed, stop=False)\n                                    time.sleep(TURN_45_DEGREES)\n                                    bridge.stop()\n                                    time.sleep(0.3)\n\n                                    # Walk backward to create clearance\n                                    bridge._publish(x=-speed, y=0.0, yaw_rate=0.0, stop=False)\n                                    time.sleep(2.0)\n                                    bridge.stop()\n                                    time.sleep(0.3)\n\n                                    # Turn a full 180° to face the opposite direction\n                                    TURN_180_DEGREES = TURN_45_DEGREES * 4  # 90°=4.5s, so 180°=9.0s\n                                    yield event("log", {"msg": "↩ Turning 180°..."})\n                                    yield event("log", {"msg": "↩ Turning 180°..."})\n                                    bridge._publish(yaw_rate=-speed, stop=False)\n                                    time.sleep(TURN_180_DEGREES)\n                                    bridge.stop()\n                                    time.sleep(0.3)\n\n                                    final_dist = bridge.get_lidar_distance()\n                                    if final_dist is None or final_dist >= SAFE_DISTANCE:\n                                        yield event("log", {"msg": "✓ Turned around — path clear, continuing in new direction..."})\n                                        path_clear = True\n                                    else:\n                                        yield event("log", {"msg": "⚠ Still blocked after turning around — stopping for new instructions."})\n                                        yield event("obstacle", {\n                                            "msg": "⚠ Surrounded by obstacles — robot stopped. Please give new instructions.",\n                                            "image": ""\n                                        })\n                                        obstacle_hit = True\n                                        break\n\n                                if path_clear:\n                                    # Resume walking forward in the new heading\n                                    bridge._publish(x=speed, y=0.0, yaw_rate=0.0, stop=False)\n\n                    if obstacle_hit:\n                        break\n\n                    # Normal end-of-segment stop\n                    bridge.stop()\n                    time.sleep(0.3)\n\n                    remaining -= this_segment\n                    elapsed_total += this_segment\n\n                    # Capture image if interval reached\n                    if round(elapsed_total - last_capture_at, 1) >= CAPTURE_INTERVAL:\n                        time.sleep(1.2)\n                        try:\n                            from datetime import datetime\n                            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n                            yield event("log", {"msg": f"Capturing image at {round(elapsed_total, 1)}s..."})\n                            filepath = bridge.take_picture()\n                            all_captured_images.append(filepath)\n                            last_capture_at = elapsed_total\n                            filename = os.path.basename(filepath)\n                            captured_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")\n                            yield event("image", {"src": f"/captures/{filename}", "label": filename, "captured_at": captured_at, "dog_id": dog_id, "waypoint_name": action.get("waypoint_name"), "route_name": action.get("route_name")})\n                            yield event("log", {"msg": f"✓ Image saved: {filename}"})\n                            yield event("log", {"msg": "✓ Path clear — continuing..."})\n                        except Exception as e:\n                            yield event("log", {"msg": f"Capture failed: {e}"})\n\n                if obstacle_hit:\n                    yield event("done", {"msg": "Robot stopped — surrounded by obstacles. Enter a new command."})\n                    return\n\n            elif action_name == "take_picture":\n                try:\n                    yield event("log", {"msg": "📷 Taking picture..."})\n                    filepath = bridge.take_picture()\n                    all_captured_images.append(filepath)\n                    filename = os.path.basename(filepath)\n                    captured_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")\n                    yield event("image", {"src": f"/captures/{filename}", "label": filename, "captured_at": captured_at, "dog_id": dog_id, "waypoint_name": action.get("waypoint_name"), "route_name": action.get("route_name")})\n                    yield event("log", {"msg": f"✓ Image saved: {filename}"})\n                    yield event("progress", {"index": i, "pct": 100, "elapsed": 0})\n                except Exception as e:\n                    yield event("error", {"msg": f"Camera failed: {e}"})\n\n            elif action_name == "turn_left":\n                bridge._publish(yaw_rate=speed, stop=False)\n                steps = int(duration * 10)\n                for step in range(steps):\n                    time.sleep(0.1)\n                    if cancel_event.is_set():\n                        emergency_stop_robot(bridge)\n                        yield event("log", {"msg": "⚠ Stop requested — halting robot."})\n                        yield event("done", {"msg": "Command stopped."})\n                        return\n                    pct = int(((step + 1) / steps) * 100)\n                    yield event("progress", {"index": i, "pct": pct, "elapsed": round((step + 1) * 0.1, 1)})\n                bridge.stop()\n                time.sleep(0.3)\n\n                if cancel_event.is_set():\n                    yield event("log", {"msg": "⚠ Stop requested — halting robot."})\n                    yield event("done", {"msg": "Command stopped."})\n                    return\n\n                # Capture after turn if duration >= 4 seconds\n                if duration >= 4.0:\n                    time.sleep(1.2)  # settle before capture\n                    try:\n                        from datetime import datetime\n                        yield event("log", {"msg": "Capturing image after turn..."})\n                        filepath = bridge.take_picture()\n                        all_captured_images.append(filepath)\n                        filename = os.path.basename(filepath)\n                        captured_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")\n                        yield event("image", {"src": f"/captures/{filename}", "label": filename, "captured_at": captured_at, "dog_id": dog_id, "waypoint_name": action.get("waypoint_name"), "route_name": action.get("route_name")})\n                        yield event("log", {"msg": f"✓ Image saved: {filename}"})\n                    except Exception as e:\n                        yield event("log", {"msg": f"Capture failed: {e}"})\n            elif action_name == "walk_backward":\n                bridge._publish(x=-speed, y=0.0, yaw_rate=0.0, stop=False)\n                bridge._publish(x=-speed, y=0.0, yaw_rate=0.0, stop=False)  \n                steps = int(duration * 10)\n                for step in range(steps):\n                    time.sleep(0.1)\n                    if cancel_event.is_set():\n                        emergency_stop_robot(bridge)\n                        yield event("log", {"msg": "⚠ Stop requested — halting robot."})\n                        yield event("done", {"msg": "Command stopped."})\n                        return\n                    pct = int(((step + 1) / steps) * 100)\n                    yield event("progress", {"index": i, "pct": pct, "elapsed": round((step + 1) * 0.1, 1)})\n                bridge.stop()\n                time.sleep(0.3)\n            elif action_name == "turn_right":\n                bridge._publish(yaw_rate=-speed, stop=False)\n                steps = int(duration * 10)\n                for step in range(steps):\n                    time.sleep(0.1)\n                    if cancel_event.is_set():\n                        emergency_stop_robot(bridge)\n                        yield event("log", {"msg": "⚠ Stop requested — halting robot."})\n                        yield event("done", {"msg": "Command stopped."})\n                        return\n                    pct = int(((step + 1) / steps) * 100)\n                    yield event("progress", {"index": i, "pct": pct, "elapsed": round((step + 1) * 0.1, 1)})\n                bridge.stop()\n                time.sleep(0.3)\n\n                if cancel_event.is_set():\n                    yield event("log", {"msg": "⚠ Stop requested — halting robot."})\n                    yield event("done", {"msg": "Command stopped."})\n                    return\n\n                # Capture after turn if duration >= 4 seconds\n                if duration >= 4.0:\n                    time.sleep(1.2)  # settle before capture\n                    try:\n                        from datetime import datetime\n                        yield event("log", {"msg": "Capturing image after turn..."})\n                        filepath = bridge.take_picture()\n                        all_captured_images.append(filepath)\n                        filename = os.path.basename(filepath)\n                        captured_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")\n                        yield event("image", {"src": f"/captures/{filename}", "label": filename, "captured_at": captured_at, "dog_id": dog_id, "waypoint_name": action.get("waypoint_name"), "route_name": action.get("route_name")})\n                        yield event("log", {"msg": f"✓ Image saved: {filename}"})\n                    except Exception as e:\n                        yield event("log", {"msg": f"Capture failed: {e}"})\n\n            elif action_name == "sit":\n                bridge.sit()\n                yield event("progress", {"index": i, "pct": 100, "elapsed": 0})\n\n            elif action_name == "stop":\n                emergency_stop_robot(bridge)\n                yield event("progress", {"index": i, "pct": 100, "elapsed": 0})\n\n        except Exception as e:\n            yield event("error", {"msg": f"Execution error: {e}"})\n            try:\n                emergency_stop_robot(bridge)\n            except Exception:\n                pass\n            return\n        \n        #hey everyone \n\n\n        yield event("action_done", {"index": i, "action": action_name})\n\n        yield event("done", {"msg": f"Completed {len(actions)} action(s)."})\n\n\n@app.route("/analyze", methods=["POST"])\ndef analyze():\n    data = request.get_json(silent=True) or {}\n    if not isinstance(data, dict):\n        return {"error": "Invalid request body"}, 400\n    requested_images = data.get("images")\n    if requested_images is None and data.get("filepath"):\n        requested_images = [{"filepath": data["filepath"]}]\n\n    if not isinstance(requested_images, list) or not requested_images:\n        return {"error": "No images provided"}, 400\n\n    capture_root = os.path.realpath(CAPTURE_DIR)\n    images = []\n    for image in requested_images:\n        if not isinstance(image, dict):\n            return {"error": "Each image must be an object"}, 400\n        filepath = image.get("filepath", "")\n        if not isinstance(filepath, str) or not filepath.strip():\n            return {"error": "Each image must include a filepath"}, 400\n\n        resolved_path = os.path.realpath(filepath.strip())\n        try:\n            is_capture = os.path.commonpath((capture_root, resolved_path)) == capture_root\n        except ValueError:\n            is_capture = False\n        if not is_capture or resolved_path == capture_root:\n            return {"error": "Invalid filepath"}, 400\n\n        waypoint_name = image.get("waypoint_name")\n        if waypoint_name is not None:\n            waypoint_name = str(waypoint_name).strip() or None\n        route_name = image.get("route_name")\n        if route_name is not None:\n            route_name = str(route_name).strip() or None\n        images.append({\n            "filepath": resolved_path,\n            "waypoint_name": waypoint_name,\n            "route_name": route_name,\n        })\n\n    route_name = str(data.get("route_name") or next(\n        (image["route_name"] for image in images if image["route_name"]),\n        "Data Center Patrol",\n    )).strip() or "Data Center Patrol"\n\n    def generate():\n        from vision.compliance_checker import check_compliance_with_nim\n        from vision.report_generator import generate_report\n        from datetime import datetime\n\n        try:\n            all_findings = []\n            for image in images:\n                filepath = image["filepath"]\n                filename = os.path.basename(filepath)\n                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n                waypoint_name = image["waypoint_name"]\n                location = f"{waypoint_name}: " if waypoint_name else ""\n                yield f"data: {json.dumps({\'type\': \'log\', \'msg\': f\'Analyzing {location}{filename}...\'})}\\n\\n"\n\n                findings = check_compliance_with_nim(filepath=filepath, timestamp=timestamp)\n                for finding in findings:\n                    finding["waypoint_name"] = waypoint_name\n                all_findings.append(findings)\n\n                high_fails = [\n                    f for f in findings\n                    if f["status"] == "FAIL" and f["severity"] in ("HIGH", "ALERT")\n                ]\n                other_fails = [\n                    f for f in findings\n                    if f["status"] == "FAIL" and f["severity"] in ("MEDIUM", "LOW")\n                ]\n                image_status = "FAIL" if high_fails else "WARNING" if other_fails else "PASS"\n                if any(f.get("rule_id") == "PHONE_001" and f["status"] == "FAIL" for f in findings):\n                    yield f"data: {json.dumps({\'type\': \'log\', \'msg\': f\'Lost cellphone detected in {filename}\'})}\\n\\n"\n\n                visible_findings = [\n                    {\n                        "rule_name": f["rule_name"],\n                        "severity": f["severity"],\n                        "status": f["status"],\n                        "remediation": f["remediation"],\n                    }\n                    for f in findings\n                ]\n                yield f"data: {json.dumps({\'type\': \'image_findings\', \'filename\': filename, \'waypoint_name\': waypoint_name, \'status\': image_status, \'findings\': visible_findings})}\\n\\n"\n\n            report, json_path, txt_path = generate_report(\n                all_findings=all_findings,\n                location="SHI Lab",\n                inspector="NemoClaw",\n                route_name=route_name,\n            )\n            total_fails = sum(\n                finding["status"] == "FAIL"\n                for findings in all_findings\n                for finding in findings\n            )\n            yield f"data: {json.dumps({\'type\': \'report_summary\', \'overall\': report[\'overall_status\'], \'total_images\': len(images), \'total_fails\': total_fails, \'report_file\': os.path.basename(txt_path), \'dog_id\': data.get(\'dog_id\', \'dog1\')})}\\n\\n"\n            yield f"data: {json.dumps({\'type\': \'done\', \'msg\': \'Analysis complete.\'})}\\n\\n"\n\n        except Exception as e:\n            yield f"data: {json.dumps({\'type\': \'error\', \'msg\': str(e)})}\\n\\n"\n\n    return Response(\n        stream_with_context(generate()),\n        mimetype="text/event-stream",\n        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"}\n    )\n\n@app.route("/api/status", methods=["GET"])\ndef api_status():\n    """\n    Returns the current system status.\n\n    Used by:\n    - Pair & Connect Screen\n    - Startup Monitoring\n    - Future Route Status Tracking\n    """\n\n    return status.get_status()\n\n@app.route("/")\ndef index():\n    return render_template("index.html")\n\n\n@app.route("/clear-image", methods=["POST"])\ndef clear_image():\n    data = request.get_json(silent=True) or {}\n    filename = (data.get("filename") or "").strip()\n\n    if not filename:\n        return {"error": "No filename provided"}, 400\n\n    safe_name = os.path.basename(filename)\n    if not safe_name or safe_name != filename:\n        return {"error": "Invalid filename"}, 400\n\n    target_path = os.path.abspath(os.path.join(CAPTURE_DIR, safe_name))\n    if os.path.commonpath([os.path.abspath(CAPTURE_DIR), target_path]) != os.path.abspath(CAPTURE_DIR):\n        return {"error": "Invalid filename"}, 400\n\n    if os.path.exists(target_path):\n        os.remove(target_path)\n\n    return {"status": "deleted", "filename": safe_name}\n\n\n@app.route("/captures/<filename>")\ndef serve_capture(filename):\n    return send_from_directory(CAPTURE_DIR, filename)\n\n\n@app.route("/reports/<filename>")\ndef serve_report(filename):\n    return send_from_directory(REPORT_DIR, filename)\n\n# ---------------------------------------------------------------------------\n# Waypoint patrol: runs a saved route (routes/*.json) on the dog\'s map.\n# The dog must be in navigation mode with rosbridge running\n# (roslaunch pug_navigation patrol.launch map:=datacenter_01 on the dog).\n# ---------------------------------------------------------------------------\n\nROUTES_DIR = os.path.join(BASE_DIR, "routes")\n_patrols = {}              # dog_id -> RouteRunner while a patrol is running\n_patrol_lock = threading.Lock()\n\n# Runner statuses that end a patrol, and how the UI should show them\n_PATROL_END = {\n    "route_completed": "done",\n    "route_stopped": "done",\n    "route_failed": "error",\n}\n\n\ndef _safe_name(text):\n    """\'Stop 9 (return)\' -> \'Stop-9-return\' for use in a filename."""\n    keep = "".join(c if c.isalnum() else "-" for c in text)\n    return "-".join(part for part in keep.split("-") if part)\n\n\n@app.route("/routes", methods=["GET"])\ndef list_routes():\n    """Route files the UI can offer in the patrol dropdown."""\n    from navigation.route_loader import load_route\n    routes = []\n    for fname in sorted(os.listdir(ROUTES_DIR)):\n        if not fname.endswith(".json"):\n            continue\n        try:\n            r = load_route(os.path.join(ROUTES_DIR, fname))\n            routes.append({"file": fname, "name": r["route_name"],\n                           "stops": len(r["waypoints"])})\n        except Exception as e:\n            routes.append({"file": fname, "name": fname, "error": str(e)})\n    return {"routes": routes}\n\n\n@app.route("/api/routes", methods=["GET"])\ndef api_routes():\n    """Every route with its waypoints, in the shape the new UI\'s Route Setup uses."""\n    from navigation.route_loader import load_route\n    routes = []\n    for fname in sorted(os.listdir(ROUTES_DIR)):\n        if not fname.endswith(".json"):\n            continue\n        try:\n            r = load_route(os.path.join(ROUTES_DIR, fname))\n        except Exception as e:\n            routes.append({"file": fname, "name": fname, "error": str(e), "waypoints": []})\n            continue\n        routes.append({\n            "file": fname,\n            "name": r["route_name"],\n            "waypoints": [{\n                "name": wp["name"],\n                "x": wp["x"], "y": wp["y"], "yaw": wp["yaw"],\n                "photo": wp["action"] == "capture_image",\n                "required": wp["required"],\n            } for wp in r["waypoints"]],\n        })\n    return {"routes": routes}\n\n\ndef _dog_status(dog):\n    """Card info for one dog: offline / online / ready, plus whether it\'s patrolling."""\n    state, label = dog_prep.dog_status(dog)\n    with _patrol_lock:\n        on_patrol = dog["id"] in _patrols\n    if on_patrol:\n        label = "On patrol"\n    ids = list(DOG_IPS)\n    return {\n        "id": dog["id"], "name": dog["name"], "ip": dog["ip"],\n        "ssh_user": dog.get("ssh_user", "hiwonder"), "ros_port": dog.get("ros_port", 9090),\n        "unit": f"Unit {ids.index(dog[\'id\']) + 1:02d}" if dog["id"] in ids else "Unit --",\n        "state": state, "label": label, "online": state != "offline",\n        "on_patrol": on_patrol, "battery": None,\n    }\n\n\n@app.route("/api/dogs", methods=["GET"])\ndef api_dogs():\n    """Live status of every configured dog (checked in parallel, ~1 s worst case)."""\n    from concurrent.futures import ThreadPoolExecutor\n    dogs = reload_dogs()\n    if not dogs:\n        return {"dogs": []}\n    with ThreadPoolExecutor(max_workers=len(dogs)) as pool:\n        return {"dogs": list(pool.map(_dog_status, dogs))}\n\n\n@app.route("/api/dogs", methods=["POST"])\ndef api_add_dog():\n    """Add a dog (from the Add / Remove Dogs dialog)."""\n    data = request.get_json(silent=True) or {}\n    dog, err = dog_prep.add_dog(data.get("name", ""), data.get("ip", ""),\n                                data.get("ssh_user") or "hiwonder", data.get("ros_port", 9090))\n    if err:\n        return {"error": err}, 400\n    reload_dogs()\n    return {"dog": dog}\n\n\n@app.route("/api/dogs/<dog_id>", methods=["DELETE"])\ndef api_remove_dog(dog_id):\n    with _patrol_lock:\n        if dog_id in _patrols:\n            return {"error": "Stop this dog\'s patrol before removing it"}, 409\n    if not dog_prep.remove_dog(dog_id):\n        return {"error": "No such dog"}, 404\n    with _bridge_lock:\n        _bridges.pop(dog_id, None)\n    reload_dogs()\n    return {"status": "removed"}\n\n\n@app.route("/api/dogs/<dog_id>/prepare", methods=["POST"])\ndef api_prepare_dog(dog_id):\n    """Pair & Connect: put the dog in patrol mode over SSH. Streams each step."""\n    dog = next((d for d in reload_dogs() if d["id"] == dog_id), None)\n    if not dog:\n        return {"error": "No such dog"}, 404\n\n    def generate():\n        for update in dog_prep.prepare_dog(dog):\n            if update.get("done") and update.get("ok"):\n                with _bridge_lock:          # drop any stale connection from before\n                    _bridges.pop(dog_id, None)\n            yield f"data: {json.dumps(update)}\\n\\n"\n\n    return Response(stream_with_context(generate()), mimetype="text/event-stream",\n                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})\n\n\n@app.route("/api/nim", methods=["GET"])\ndef api_nim():\n    """Is the AI model server (Qwen) answering? Used by the NIM card."""\n    models_url = NIM_URL.rsplit("/chat/completions", 1)[0] + "/models"\n    try:\n        r = http_requests.get(models_url, headers=nim_headers(), timeout=1.5)\n        r.raise_for_status()\n        ids = [m.get("id") for m in r.json().get("data", [])]\n        loaded = NIM_MODEL in ids\n        return {"up": True, "model": NIM_MODEL, "loaded": loaded, "available": ids,\n                "label": "AI model ready" if loaded else f"Server up, but \'{NIM_MODEL}\' not loaded"}\n    except Exception:\n        return {"up": False, "model": NIM_MODEL, "loaded": False, "available": [],\n                "label": "AI model offline (start Qwen to analyze photos)"}\n\n\n@app.route("/api/nim/<action>", methods=["POST"])\ndef api_nim_control(action):\n    """Start or stop the Qwen server kit on this computer (config_nim.yaml: server_dir)."""\n    import subprocess\n    from nim_config import NIM_SERVER_DIR\n    if action not in ("start", "stop"):\n        return {"error": "Use start or stop"}, 400\n    if not NIM_SERVER_DIR or not os.path.isdir(NIM_SERVER_DIR):\n        return {"error": "Set server_dir in config_nim.yaml to the Qwen kit folder"}, 400\n    script = os.path.join(NIM_SERVER_DIR, "linux", f"{action}.sh")\n    if not os.path.exists(script):\n        return {"error": f"{script} not found"}, 400\n    args = ["bash", script] + (["--no-harness", "-b"] if action == "start" else [])\n    subprocess.Popen(args, cwd=NIM_SERVER_DIR, stdin=subprocess.DEVNULL,\n                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,\n                     start_new_session=True)\n    return {"status": f"{action} requested"}\n\n\n@app.route("/new")\ndef new_ui():\n    """The new UI (templates/new_ui.html). The old UI stays at /."""\n    return render_template("new_ui.html")\n\n\n@app.route("/patrol/start", methods=["POST"])\ndef patrol_start():\n    import queue\n    from navigation.route_loader import load_route\n    from navigation.route_runner import RouteRunner\n    from navigation.navigator import RosNavigator\n\n    data = request.get_json(silent=True) or {}\n    dog_id = data.get("dog_id", "dog1")\n    route_file = os.path.basename(data.get("route", "data_center.json"))\n    dog_name = DOG_NAMES.get(dog_id, dog_id)\n\n    with _patrol_lock:\n        if dog_id in _patrols:\n            return {"error": f"{dog_name} is already on patrol"}, 409\n\n    try:\n        route = load_route(os.path.join(ROUTES_DIR, route_file))\n    except Exception as e:\n        return {"error": f"Could not load route {route_file}: {e}"}, 400\n\n    events = queue.Queue()\n\n    def generate():\n        def sse(kind, payload):\n            return f"data: {json.dumps({\'type\': kind, **payload})}\\n\\n"\n\n        yield sse("log", {"msg": f"Connecting to {dog_name}..."})\n        try:\n            bridge = get_bridge(dog_id)\n            navigator = RosNavigator(bridge.client)\n        except Exception as e:\n            yield sse("error", {"msg": f"{e}. Is patrol.launch running on the dog?"})\n            return\n\n        def capture(waypoint_name):\n            path = bridge.take_picture(save_dir=CAPTURE_DIR)\n            stamp = datetime.now().strftime("%Y%m%d_%H%M%S")\n            new_path = os.path.join(\n                CAPTURE_DIR, f"{dog_name}_{_safe_name(waypoint_name)}_{stamp}.jpg")\n            os.replace(path, new_path)\n            return new_path\n\n        runner = RouteRunner(navigator, dog_name, capture=capture, on_event=events.put)\n        with _patrol_lock:\n            _patrols[dog_id] = runner\n\n        def run():\n            try:\n                runner.run(route)\n            except Exception as e:\n                events.put({"status": "route_failed", "message": str(e),\n                            "waypoint": 0, "total": 0, "waypoint_name": None})\n            finally:\n                try:\n                    navigator.close()\n                except Exception:\n                    pass\n                with _patrol_lock:\n                    _patrols.pop(dog_id, None)\n                events.put(None)  # end of stream\n\n        threading.Thread(target=run, daemon=True).start()\n\n        steps = [wp["name"] for wp in route["waypoints"]]\n        yield sse("plan", {"actions": steps, "total": len(steps)})\n\n        while True:\n            try:\n                e = events.get(timeout=15)\n            except queue.Empty:\n                yield ": keep-alive\\n\\n"\n                continue\n            if e is None:\n                break\n\n            st = e.get("status")\n            where = f"[{e.get(\'waypoint\')}/{e.get(\'total\')}] {e.get(\'waypoint_name\') or \'\'}".strip()\n            msg = f"{where} {st.replace(\'_\', \' \')}"\n            if e.get("message"):\n                msg += f": {e[\'message\']}"\n            yield sse("log", {"msg": msg})\n\n            idx = (e.get("waypoint") or 1) - 1\n            if st == "navigating":\n                yield sse("action_start", {"index": idx, "action": e["waypoint_name"],\n                                           "total": e.get("total")})\n            elif st in ("arrived", "skipped"):\n                yield sse("action_done", {"index": idx, "action": e["waypoint_name"]})\n            elif st == "captured" and e.get("image"):\n                label = os.path.basename(e["image"])\n                yield sse("image", {\n                    "src": f"/captures/{label}", "label": label,\n                    "captured_at": e.get("time", ""), "dog_id": dog_id,\n                    "waypoint_name": e.get("waypoint_name"),\n                    "route_name": route["route_name"],\n                })\n            elif st in _PATROL_END:\n                yield sse(_PATROL_END[st], {"msg": f"{route[\'route_name\']}: {st.replace(\'_\', \' \')}"})\n\n    return Response(\n        stream_with_context(generate()),\n        mimetype="text/event-stream",\n        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},\n    )\n\n\ndef _stop_patrol(dog_id):\n    """Cancel a running patrol for this dog, if any. Returns True if one was running."""\n    with _patrol_lock:\n        runner = _patrols.get(dog_id)\n    if runner:\n        runner.stop()\n        return True\n    return False\n\n\n@app.route("/patrol/stop", methods=["POST"])\ndef patrol_stop():\n    data = request.get_json(silent=True) or {}\n    dog_id = data.get("dog_id", "dog1")\n    was_running = _stop_patrol(dog_id)\n    try:\n        emergency_stop_robot(get_bridge(dog_id))\n    except Exception:\n        pass\n    return {"status": "stopped" if was_running else "not_running"}\n\n\n@app.route("/cancel", methods=["POST"])\ndef cancel():\n    data = request.get_json(silent=True) or {}\n    dog_id = data.get("dog_id", "dog1")\n    _stop_patrol(dog_id)  # cancel the navigation goal first, then halt the legs\n    try:\n        bridge = get_bridge(dog_id)\n        emergency_stop_robot(bridge)\n    except Exception:\n        pass\n    cancel_event.set()\n    return {"status": "cancelled"}\n\n@app.route("/command", methods=["POST"])\ndef command():\n    data = request.get_json()\n    user_input = data.get("input", "").strip()\n    dog_id = data.get("dog_id", "dog1")\n\n    if not user_input:\n        return {"error": "Empty input"}, 400\n\n    return Response(\n        stream_with_context(stream_command(user_input, dog_id)),\n        mimetype="text/event-stream",\n        headers={\n            "Cache-Control": "no-cache",\n            "X-Accel-Buffering": "no"\n        }\n    )\n\n\nif __name__ == "__main__":\n    print("NemoClaw UI running at http://localhost:5000")\n    app.run(debug=False, threaded=True, port=5000)\n', 'nim_config.py': '"""One place for the model server settings.\n\nEvery file that talks to the model (app.py, vision/compliance_checker.py,\nvision/nim_vision_client.py) reads its URL and model name from here, so\nswitching models means editing config_nim.yaml only.\n\nEnvironment variables override the file, which is handy for quick tests:\n    NIM_URL=http://192.168.0.50:8000/v1/chat/completions python3 app.py\n    NIM_MODEL=qwen python3 app.py\n"""\n\nimport os\nimport re\n\n_DEFAULTS = {\n    "base_url": "http://localhost:8000/v1/chat/completions",\n    "model": "qwen",\n}\n\n_CONFIG_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "config_nim.yaml")\n\n\ndef _load_file():\n    """Read config_nim.yaml. Uses PyYAML if installed, else a tiny parser."""\n    if not os.path.exists(_CONFIG_PATH):\n        return {}\n    try:\n        import yaml\n        with open(_CONFIG_PATH) as f:\n            data = yaml.safe_load(f) or {}\n        return data.get("nim", {}) or {}\n    except ImportError:\n        values = {}\n        with open(_CONFIG_PATH) as f:\n            for line in f:\n                line = line.split("#", 1)[0].strip()\n                if ":" in line and not line.endswith(":"):\n                    key, value = line.split(":", 1)\n                    values[key.strip()] = value.strip().strip(\'"\').strip("\'")\n        return values\n\n\n_file = _load_file()\n\nNIM_URL = os.environ.get("NIM_URL") or _file.get("base_url") or _DEFAULTS["base_url"]\nNIM_MODEL = os.environ.get("NIM_MODEL") or _file.get("model") or _DEFAULTS["model"]\nNIM_API_KEY = os.environ.get("NIM_API_KEY") or None\n\n# Folder of the Qwen one-click kit (has linux/start.sh); lets the UI start/stop it.\nNIM_SERVER_DIR = os.path.expanduser(\n    os.environ.get("NIM_SERVER_DIR") or _file.get("server_dir") or "")\n\n# Qwen-style "thinking" models can spend hundreds of tokens reasoning before\n# they answer. For short YES/NO checks and JSON plans that is slow and can run\n# out of max_tokens before the answer appears, so it is switched off by default.\n# Set  disable_thinking: false  in config_nim.yaml to turn thinking back on.\n_dt = os.environ.get("NIM_DISABLE_THINKING", str(_file.get("disable_thinking", "true")))\nDISABLE_THINKING = str(_dt).strip().lower() not in ("false", "0", "no")\n\n\ndef extra_params():\n    """Extra request fields to merge into every chat-completion payload."""\n    if DISABLE_THINKING:\n        # vLLM passes this to the model\'s chat template (Qwen3-style switch).\n        # Templates that don\'t use it simply ignore it.\n        return {"chat_template_kwargs": {"enable_thinking": False}}\n    return {}\n\n\ndef headers():\n    """HTTP headers for the model server (adds the API key only if one is set)."""\n    h = {"Content-Type": "application/json"}\n    if NIM_API_KEY:\n        h["Authorization"] = f"Bearer {NIM_API_KEY}"\n    return h\n\n\n_THINK_RE = re.compile(r"<think>.*?</think>", re.DOTALL | re.IGNORECASE)\n\n\ndef extract_answer(message):\n    """Return the model\'s final answer text from a chat-completion message.\n\n    Works for both models:\n    - Qwen (and most models): the answer is in "content". If the server was\n      started without a reasoning parser, the thinking arrives inline as\n      <think>...</think> before the answer, so it is stripped here.\n    - Nemotron NIM: sometimes puts everything in "reasoning" and leaves\n      "content" empty, so that is used as a fallback.\n    """\n    content = message.get("content") or ""\n    if "</think>" in content.lower():\n        content = _THINK_RE.sub("", content)\n        # unterminated or leading-only think block: keep what follows </think>\n        if "</think>" in content.lower():\n            content = re.split(r"</think>", content, flags=re.IGNORECASE)[-1]\n    content = content.strip()\n    if content:\n        return content\n    return (message.get("reasoning") or message.get("reasoning_content") or "").strip()\n', 'config_nim.yaml': '# Model server settings. Read by nim_config.py.\n# To switch models, change "model" to the name the server was started with\n# (vLLM: the value of --served-model-name). Restart app.py afterwards.\n#\n# Do NOT put API keys in this file - the repo is public.\n# If a key is needed, set it in the terminal instead:  export NIM_API_KEY=...\nnim:\n  base_url: "http://localhost:8888/v1/chat/completions"\n  model: "qwen3.8-27b-exl3-4.0bpw"\n  # Skip the model\'s long "thinking" step for faster, more reliable short answers\n  disable_thinking: true\n  # Qwen one-click kit folder, so the UI\'s AI card can start/stop it\n  server_dir: "~/Qwen3.8-27B-16gb-NVIDIA-GPUS-one-click-install"\n', 'templates/new_ui.html': '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agentic Paw Patrol</title>\n    <style>\n    :root{--bg:#071421;--panel:#0b1b2b;--line:#274059;--text:#f2f7ff;--muted:#91a7c1;--blue:#1684f8;--green:#31df79;--red:#ff6574}*{box-sizing:border-box}body{margin:0;background:#04101c;color:var(--text);font:14px Segoe UI,Arial}.app{height:100vh;display:grid;grid-template-columns:205px 1fr}.side{padding:24px 14px;background:#091927;border-right:1px solid var(--line)}.brand{font-size:19px;font-weight:700;margin:0 10px 30px}.brand small{display:block;color:#9db7d2;font-size:12px}.nav button{display:block;width:100%;padding:12px;border:0;border-radius:7px;background:transparent;color:#b9cae0;text-align:left;margin:5px 0}.nav button.active{background:#114b8c;color:white}.main{min-width:0}.pair{height:100vh;overflow:auto;padding:24px}.pairHead{display:flex;gap:24px;justify-content:space-between;align-items:stretch}.pair h1{margin:0;font-size:30px}.muted{color:var(--muted)}.card{background:linear-gradient(145deg,#0c1b2a,#0a1826);border:1px solid var(--line);border-radius:9px}.nim{min-width:500px;padding:15px 20px;display:flex;align-items:center;gap:16px}.nim strong{flex:1}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;background:var(--green);margin-right:7px}.nim button,.disconnect{border:1px solid var(--red);background:transparent;color:#ff8791;border-radius:7px;padding:10px 18px}.dogGrid{display:grid;grid-template-columns:repeat(4,minmax(190px,1fr));gap:15px;margin-top:18px}.dogCard{padding:14px;min-height:250px;position:relative;cursor:pointer}.dogCard.selected{border:2px solid #339cff}.dogCard.offline{opacity:.55;cursor:not-allowed}.check{position:absolute;width:23px;height:23px;border:2px solid #7189a3;border-radius:5px;display:grid;place-items:center}.selected .check{background:#1684f8;border-color:#57b0ff}.robot{height:130px;margin:5px 20px;background:linear-gradient(135deg,transparent 28%,#bac3c9 29% 52%,#354653 53% 65%,transparent 66%);filter:drop-shadow(0 15px 12px #0008)}.pairFoot{margin-top:16px;padding:14px;display:flex;justify-content:space-between;align-items:center}.primary{border:1px solid #62b6ff;background:linear-gradient(#1684f8,#0862ce);color:white;border-radius:7px;padding:12px 25px}.primary:disabled{opacity:.4}.dogView{display:none;height:100vh}.top{height:88px;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:15px 25px}.avatar{width:55px;height:55px;border-radius:50%;background:radial-gradient(circle,#bec8cf 25%,#263a4b 27% 50%,#aeb8bf 52%);margin-right:14px}.identity h2{margin:0}.health{display:flex;gap:22px;margin-left:28px}.disconnect{margin-left:auto}.workspace{height:calc(100vh - 88px);padding:13px;display:grid;grid-template-columns:1.15fr .85fr;gap:13px}.routeCard{padding:14px;display:flex;flex-direction:column}.routeHead{display:flex;justify-content:space-between}.map{position:relative;flex:1;min-height:350px;margin:12px 0;border:1px solid #34516e;border-radius:7px;background:linear-gradient(90deg,#11283a 1px,transparent 1px),linear-gradient(#11283a 1px,transparent 1px);background-size:28px 28px}.racks{position:absolute;inset:88px 115px;display:flex;justify-content:space-between;gap:45px;padding:16px}.rack{width:55px;background:repeating-linear-gradient(#283849 0 2px,#111f2e 2px 6px);border:1px solid #617185}.routeSvg{position:absolute;inset:0;width:100%;height:100%}.base,.done{fill:none;stroke-width:9;stroke-linecap:round;stroke-linejoin:round}.base{stroke:#8295aa}.done{stroke:#1791ff}.marker{fill:var(--green);stroke:white;stroke-width:5}.legend{display:flex;gap:22px;color:#c5d3e2}.routeActions{margin-top:auto;display:grid;grid-template-columns:1fr 220px;gap:10px}.routeBtn{width:100%}.emergencyStopBtn{border:1px solid #ff6675;background:linear-gradient(#a92335,#751725);color:white;border-radius:7px;padding:12px 18px;font-weight:700;cursor:pointer}.emergencyStopBtn.active{background:#39131a;color:#ff9da6}.emergencyStopBtn:disabled{cursor:not-allowed;opacity:.8}.right{padding:12px;display:grid;grid-template-rows:auto 1fr}.tabs{display:grid;grid-template-columns:1fr 1fr;margin:-12px -12px 12px}.tabs button{padding:14px;border:0;border-bottom:2px solid transparent;background:#081725;color:#9db1c9}.tabs button.active{background:#153d6c;color:white;border-color:#2fa0ff}.panel{min-height:0}.images{height:100%;display:grid;grid-template-rows:auto 1fr 100px;gap:10px}.photo,.thumb{border:1px solid #36506b;border-radius:7px;background:linear-gradient(90deg,#172530,#bec8c9 19%,#27343d 24% 43%,#c1c9c9 48%,#182630 53% 72%,#bdc6c7 77%,#192631)}.thumbs{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.commands{height:100%;display:grid;grid-template-rows:auto 1fr auto;gap:12px}.history{overflow:auto;border:1px solid var(--line);border-radius:8px;padding:12px;display:flex;flex-direction:column;gap:9px}.empty{margin:auto;color:#7d93ad}.message{align-self:flex-end;max-width:85%;background:#125baa;border:1px solid #3ea2ff;border-radius:11px 11px 3px 11px;padding:10px}.message small{display:block;color:#c2ddfb;text-align:right;margin-top:5px}.chat{display:grid;grid-template-columns:1fr 48px;gap:8px}.chat input{border:1px solid #496b8c;border-radius:8px;background:#091827;color:white;padding:13px}.chat button{border:0;border-radius:8px;background:#147bed;color:white;font-size:20px}.hidden{display:none}\n    /* ---------- Route Setup ---------- */\n    .navLabel{margin:22px 12px 6px;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#5f7790}\n    .setup{display:none;height:100vh;overflow:auto;padding:28px}\n    .rsWrap{max-width:1240px;margin:0 auto;display:flex;flex-direction:column;gap:20px}\n    .rsHead{display:flex;flex-wrap:wrap;gap:20px;align-items:flex-end;justify-content:space-between}\n    .rsHead h1{margin:0;font-size:30px}\n    .rsTitle{display:flex;align-items:center;gap:12px;flex-wrap:wrap}\n    .rsBadge{display:inline-flex;align-items:center;gap:7px;padding:4px 11px;border-radius:999px;font-size:12px;font-weight:600;background:#0f2a1d;border:1px solid #1d4a33;color:#6ff0a8}\n    .rsBadge i{width:7px;height:7px;border-radius:50%;background:#35e08a}\n    .rsBadge.bad{background:#2a1218;border-color:#5a2430;color:#ff8a95}.rsBadge.bad i{background:var(--red)}\n    .rsControls{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end}\n    .rsField{display:flex;flex-direction:column;gap:6px}\n    .rsLabel{font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:#6b829b}\n    .rsSeg{display:flex;padding:3px;background:#071421;border:1px solid #1d3248;border-radius:10px}\n    .rsSeg button{border:0;border-radius:7px;padding:8px 18px;min-height:38px;background:transparent;color:#8aa1ba;font:500 14px Segoe UI,Arial;cursor:pointer}\n    .rsSeg button[aria-pressed="true"]{background:#12324f;color:#fff;font-weight:600}\n    .rsInput,.rsSelect{height:44px;background:#071421;color:var(--text);border:1px solid #1d3248;border-radius:10px;padding:0 12px;font:500 14px Segoe UI,Arial}\n    .rsInput:focus,.rsSelect:focus{outline:none;border-color:#2f8cff;box-shadow:0 0 0 3px rgba(47,140,255,.18)}\n    .rsGhost{height:44px;border:1px solid #1d3248;background:transparent;color:#cfe0f5;border-radius:10px;padding:0 16px;cursor:pointer;font:500 14px Segoe UI,Arial}\n    .rsGhost:hover{border-color:#3f6286}\n    .rsNew{display:flex;gap:8px}.rsNew.hidden{display:none}\n    .rsRow{display:flex;flex-wrap:wrap;gap:20px}\n    .rsCard{background:#0a1826;border:1px solid #1b2f44;border-radius:14px;padding:22px;display:flex;flex-direction:column;gap:16px;min-width:0}\n    .rsCard h2{margin:0;font-size:15px;font-weight:600;color:#dbe7f4}\n    .rsCardHead{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}\n    .rsPose{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}\n    .rsPose div{background:#071421;border:1px solid #1b2f44;border-radius:10px;padding:12px 14px}\n    .rsPose b{display:block;font:600 24px Consolas,monospace;margin-top:2px}\n    .rsPose b span{font-size:13px;color:#6b829b;margin-left:4px}\n    .rsMap{background:#071421;border:1px solid #1b2f44;border-radius:10px;overflow:hidden}\n    .rsMap svg{display:block;width:100%;height:auto}\n    .rsLegend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:#8aa1ba}\n    .rsLegend span{display:inline-flex;align-items:center;gap:7px}\n    .rsLegend i{width:10px;height:10px;border-radius:50%}\n    .rsOption{display:flex;align-items:center;justify-content:space-between;gap:12px;background:#071421;border:1px solid #1b2f44;border-radius:10px;padding:11px 14px;min-height:48px;cursor:pointer}\n    .rsOption span span{display:block}\n    .rsOption small{color:#8aa1ba;font-size:12px}\n    .rsOption input{width:18px;height:18px;accent-color:#2f8cff}\n    .rsRecord{height:50px;border:0;border-radius:10px;background:#1f7ae6;color:#fff;font:600 15px Segoe UI,Arial;display:flex;align-items:center;justify-content:center;gap:10px;cursor:pointer}\n    .rsRecord:hover{background:#2a86f0}\n    .rsRecord:disabled{background:#13283b;color:#5f7790;cursor:not-allowed}\n    .rsRecord kbd{font:500 11px Consolas,monospace;padding:2px 7px;border-radius:5px;background:rgba(255,255,255,.2)}\n    .rsMsg{min-height:20px;font-size:13px;color:#6ff0a8}.rsMsg.err{color:#ff8a95}\n    .rsHelp{margin-top:auto;border-top:1px solid #1b2f44;padding-top:14px;display:flex;flex-direction:column;gap:8px;color:#8aa1ba;font-size:13px}\n    .rsHelp b{color:#cfe0f5}\n    .rsTableWrap{overflow-x:auto}\n    .rsTable{width:100%;border-collapse:collapse;min-width:760px;font-variant-numeric:tabular-nums}\n    .rsTable th{text-align:left;color:#6b829b;font-size:11px;letter-spacing:.08em;text-transform:uppercase;font-weight:600;padding:8px 10px}\n    .rsTable td{padding:10px;border-top:1px solid #142739}\n    .rsTable tr.sel td{background:#0d2034}\n    .rsNum{display:inline-grid;place-items:center;width:26px;height:26px;border-radius:50%;background:#2f8cff;font:600 12px Consolas,monospace}\n    .rsNum.plain{background:#3a5470}\n    .rsMono{font-family:Consolas,monospace;color:#a9bdd2}\n    .rsName{width:100%;background:transparent;border:1px solid transparent;border-radius:7px;color:var(--text);padding:5px 8px;margin-left:-8px;font:600 14px Segoe UI,Arial}\n    .rsName:hover{border-color:#1d3248}.rsName:focus{outline:none;border-color:#2f8cff;background:#071421}\n    .rsTag{border:0;cursor:pointer;font:600 12px Segoe UI,Arial;padding:4px 10px;border-radius:999px}\n    .rsTag.photo{background:#0f2440;color:#8cc2ff}.rsTag.nophoto{background:#13202d;color:#6b829b}\n    .rsTag.req{background:#13283b;color:#cfe0f5}.rsTag.opt{background:#2b2410;color:#f5c46b}\n    .rsActs{text-align:right;white-space:nowrap}\n    .rsIcon{width:34px;height:34px;border:1px solid #1d3248;background:transparent;color:#8aa1ba;border-radius:8px;cursor:pointer}\n    .rsIcon:disabled{color:#3a4f66;cursor:default}\n    .rsDel{height:34px;border:1px solid #4a1f28;background:transparent;color:#ff8a95;border-radius:8px;padding:0 12px;cursor:pointer;font:500 13px Segoe UI,Arial}\n    .rsEmpty{padding:28px 10px;text-align:center;color:#7d93ad}\n    \n    @media(max-width:1000px){.setup{padding:18px}.rsPose b{font-size:20px}.dogGrid{grid-template-columns:repeat(2,1fr)}.pairHead{display:block}.nim{min-width:0;margin-top:15px}.workspace{grid-template-columns:1fr}.right{display:none}}\n    \n    /* ---------- Dog Management Popup ---------- */\n    .dogListHead{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:18px}\n    .dogListHead h3{margin:0}\n    .manageDogsBtn{border:1px solid #42698e;background:#0b1b2b;color:#dcecff;border-radius:9px;padding:10px 16px;font-weight:600;cursor:pointer;position:relative;z-index:1}\n    .manageDogsBtn:hover{border-color:#62b6ff;background:#10243a}\n    .dogModalBackdrop{display:none;position:fixed;inset:0;z-index:10000;background:rgba(1,8,14,.82);align-items:center;justify-content:center;padding:20px;pointer-events:auto}\n    .dogModalBackdrop.open{display:flex}\n    .dogModal{width:min(820px,100%);max-height:90vh;overflow:auto;padding:22px;position:relative;pointer-events:auto}\n    .dogModalHead{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}\n    .dogModalHead h2{margin:0}\n    .dogModalClose{width:40px;height:40px;border:1px solid #36536f;background:#071421;color:#dcecff;border-radius:8px;font-size:21px;cursor:pointer}\n    .dogForm{display:grid;grid-template-columns:1fr 1.2fr 1fr .8fr;gap:12px;margin-top:20px}\n    .dogForm label{display:flex;flex-direction:column;gap:6px;color:#7890a9;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}\n    .dogForm input{height:44px;border:1px solid #29445f;border-radius:8px;background:#071421;color:#f2f7ff;padding:0 11px;outline:none}\n    .dogForm input:focus{border-color:#2f8cff;box-shadow:0 0 0 3px rgba(47,140,255,.17)}\n    .dogFormActions{grid-column:1/-1;display:flex;justify-content:flex-end;gap:10px;margin-top:2px}\n    .addDogBtn{min-width:150px;cursor:pointer;pointer-events:auto;position:relative;z-index:2}\n    .dogFormError{grid-column:1/-1;min-height:18px;color:#ff8a95;font-size:13px}\n    .managedDogs{display:flex;flex-direction:column;gap:9px;margin-top:10px}\n    .managedDog{display:grid;grid-template-columns:1.1fr 1.25fr 1fr .8fr auto;gap:12px;align-items:center;padding:11px 12px;border:1px solid #1e374e;border-radius:9px;background:#071421}\n    .managedDog small{display:block;color:#7289a1;margin-top:3px}\n    .removeDogBtn{border:1px solid #59242e;background:transparent;color:#ff8a95;border-radius:7px;padding:8px 12px;cursor:pointer}\n    @media(max-width:850px){.dogForm{grid-template-columns:1fr 1fr}.managedDog{grid-template-columns:1fr 1fr}.removeDogBtn{grid-column:1/-1}.dogModal{max-height:94vh}}\n\n    </style></head><body><div class="app"><aside class="side"><div class="brand">Robotic Dogs<small>Agentic Paw Patrol</small></div><nav class="nav"><button id="pairNav" class="active">▣ &nbsp; Pair & Connect</button><div id="dogNav"></div><div class="navLabel">Setup</div><button id="setupNav">⌖ &nbsp; Route Setup</button></nav></aside><main class="main"><section id="pair" class="pair"><div class="pairHead"><div><h1>Pair & Connect</h1><p class="muted">Select any available robotic dogs to connect with.</p></div><div class="nim card"><span style="font-size:28px">◉</span><strong>AI Model (Qwen)<small id="nimDetail" class="muted" style="display:block">Checking…</small></strong><span id="nimStatus"><i id="nimDot" class="dot"></i><b id="nimText">…</b></span><button id="nimBtn">Check again</button></div></div><div class="dogListHead"><h3>Available Robotic Dogs</h3><button id="manageDogsBtn" class="manageDogsBtn" type="button">+ Add / Remove Dogs</button></div><div id="dogGrid" class="dogGrid"></div><div class="pairFoot card"><span id="summary">0 dogs selected</span><button id="pairBtn" class="primary" disabled>Pair & Connect</button></div></section><section id="dogView" class="dogView"><header class="top"><div class="avatar"></div><div class="identity"><h2 id="dogName"></h2><small id="unit"></small></div><div class="health"><span><i class="dot"></i>Online</span><span>▣ <b id="battery"></b></span><span>⌁ Connected</span></div><button id="disconnect" class="disconnect">Disconnect</button></header><div class="workspace"><section class="routeCard card"><div class="routeHead"><b>Route Progress</b><span id="percent"></span></div><div class="map"><div class="racks"><div class="rack"></div><div class="rack"></div><div class="rack"></div><div class="rack"></div></div><svg class="routeSvg" viewBox="0 0 600 340" preserveAspectRatio="none"><polyline id="base" class="base" points="85,285 85,55 515,55 515,285 85,285"/><polyline id="done" class="done" points="85,285 85,55 515,55 515,285 85,285"/><circle id="marker" class="marker" r="10"/></svg></div><div class="legend">🔵 Completed &nbsp; 🟢 Current Position &nbsp; ⚪ Remaining</div><p><b>Current Task</b><br><span id="task" style="color:#8ec5ff"></span></p><div class="routeActions"><button id="routeBtn" class="primary routeBtn">▶ Go on your inspection route</button><button id="emergencyStopBtn" class="emergencyStopBtn">■ Emergency Stop</button></div></section><aside class="right card"><div class="tabs"><button id="imagesTab" class="active">Images</button><button id="commandsTab">Emergency Commands</button></div><div id="imagesPanel" class="panel images"><b>Live Images</b><div class="photo"></div><div class="thumbs"><div class="thumb"></div><div class="thumb"></div><div class="thumb"></div></div></div><div id="commandsPanel" class="panel commands hidden"><div><b>Emergency Commands</b><p class="muted">Send a direct instruction to the selected dog.</p></div><div id="history" class="history"></div><div class="chat"><input id="commandInput" placeholder="Type an exact movement command..."><button id="send">➤</button></div></div></aside></div></section><section id="setup" class="setup" aria-labelledby="rsH1">\n    <div class="rsWrap">\n    <header class="rsHead">\n    <div>\n    <div class="rsTitle"><h1 id="rsH1">Route Setup</h1><span id="rsBadge" class="rsBadge"><i></i><span id="rsBadgeText">Pumbaa localized</span></span></div>\n    <p class="muted" style="margin:6px 0 0">Walk the dog to each inspection spot and press Record. </p>\n    </div>\n    <div class="rsControls">\n    <div class="rsField"><span class="rsLabel" id="rsDogLabel">Dog</span><div id="rsDogs" class="rsSeg" role="group" aria-labelledby="rsDogLabel"></div></div>\n    <div class="rsField" style="min-width:220px"><label class="rsLabel" for="rsRoute">Route</label><select id="rsRoute" class="rsSelect"></select></div>\n    <button id="rsNewToggle" class="rsGhost" type="button" aria-expanded="false">+ New route</button>\n    </div>\n    </header>\n    <form id="rsNewForm" class="rsNew hidden" style="justify-content:flex-end">\n    <input id="rsNewName" class="rsInput" placeholder="Route name, e.g. Ops Center Patrol" aria-label="New route name" style="width:300px">\n    <button class="rsGhost" type="submit">Create</button>\n    </form>\n    \n    <div class="rsRow">\n    <section class="rsCard" style="flex:999 1 560px">\n    <div class="rsCardHead"><h2>Dog position</h2><button id="rsRecenter" class="rsGhost" type="button" style="height:32px;font-size:12.5px;padding:0 12px">Recenter map</button></div>\n    <div class="rsPose" aria-live="polite">\n    <div><span class="rsLabel">X</span><b id="rsX">–</b></div>\n    <div><span class="rsLabel">Y</span><b id="rsY">–</b></div>\n    <div><span class="rsLabel">Facing</span><b id="rsYaw">–</b></div>\n    </div>\n    <div class="rsMap"><svg id="rsMap" viewBox="0 0 640 340" role="img" aria-label="Map of recorded stops and the dog\'s position"></svg></div>\n    <div class="rsLegend"><span><i style="background:#2f8cff"></i>Photo stop</span><span><i style="background:#3a5470"></i>No photo</span><span><i style="background:#35e08a"></i>Dog</span></div>\n    </section>\n    \n    <section class="rsCard" style="flex:1 1 360px">\n    <h2>Record a waypoint here</h2>\n    <div class="rsField"><label class="rsLabel" for="rsWpName">Name</label><input id="rsWpName" class="rsInput" placeholder="e.g. Corner 1" style="height:46px;font-size:15px"></div>\n    <div style="display:flex;flex-direction:column;gap:8px">\n    <label class="rsOption"><span><span style="font-weight:600">Take a photo here</span><small>Sent for compliance analysis</small></span><input id="rsPhoto" type="checkbox" checked></label>\n    <label class="rsOption"><span><span style="font-weight:600">Required stop</span><small>Route ends if the dog can\'t reach it</small></span><input id="rsRequired" type="checkbox" checked></label>\n    </div>\n    <button id="rsRecord" class="rsRecord" type="button">Record at dog\'s position <kbd>Enter</kbd></button>\n    <div id="rsMsg" class="rsMsg" role="status"></div>\n    <div class="rsHelp"><b>How to use</b><span>1. Start the dog on the taped start spot.</span><span>2. Drive it to a spot and point it at what to photograph.</span><span>3. Name it and press Record. End with "Home".</span></div>\n    </section>\n    </div>\n    \n    <section class="rsCard">\n    <div class="rsCardHead"><h2 id="rsListTitle">Waypoints</h2><span id="rsCount" class="rsMono" style="font-size:12px;color:#6b829b"></span></div>\n    <div class="rsTableWrap"><table class="rsTable">\n    <thead><tr><th style="width:44px">#</th><th>Name</th><th>Position</th><th>Facing</th><th>Photo</th><th>Stop</th><th style="text-align:right">Actions</th></tr></thead>\n    <tbody id="rsBody"></tbody>\n    </table></div>\n    </section>\n    </div>\n    </section>\n    </main></div>\n    \n    <div id="dogModalBackdrop" class="dogModalBackdrop" role="dialog" aria-modal="true" aria-labelledby="dogModalTitle">\n      <section class="dogModal card">\n        <div class="dogModalHead">\n          <div><h2 id="dogModalTitle">Add or Remove Dogs</h2><p class="muted">Configure the connection details used for each robotic dog.</p></div>\n          <button id="closeDogModal" class="dogModalClose" type="button" aria-label="Close">×</button>\n        </div>\n        <form id="addDogForm" class="dogForm" novalidate>\n          <label>Dog name<input id="newDogName" type="text" autocomplete="off" placeholder="e.g. Pumbaa"></label>\n          <label>IP address<input id="newDogIp" type="text" autocomplete="off" placeholder="e.g. 192.168.0.60"></label>\n          <label>SSH username<input id="newDogUser" type="text" autocomplete="off" placeholder="e.g. ubuntu"></label>\n          <label>ROS port<input id="newDogPort" type="number" min="1" max="65535" value="9090"></label>\n          <div id="dogFormError" class="dogFormError" role="alert"></div>\n          <div class="dogFormActions">\n            <button id="cancelAddDog" class="rsGhost" type="button">Cancel</button>\n            <button id="addDogBtn" class="primary addDogBtn" type="button">Add Dog</button>\n          </div>\n        </form>\n        <h3>Configured Dogs</h3>\n        <div id="managedDogs" class="managedDogs"></div>\n      </section>\n    </div>\n\n    <script>\n    const dogs={};   // filled from /api/dogs by loadDogs()\n    let selected=new Set(),current=\'\',nimOn=false;const dogStates=Object.fromEntries(Object.keys(dogs).map(n=>[n,{stopped:false,running:false}]));const histories=Object.fromEntries(Object.keys(dogs).map(n=>[n,[]]));const $=id=>document.getElementById(id);\n    function renderCards(){$(\'dogGrid\').innerHTML=Object.entries(dogs).map(([n,d])=>`<article class="dogCard card ${selected.has(n)?\'selected\':\'\'} ${d.online?\'\':\'offline\'}" data-dog="${n}"><div class="check">${selected.has(n)?\'✓\':\'\'}</div><div class="robot"></div><h3>${n}</h3><span class="muted">${d.unit} · ${d.ip||\'No IP\'}</span><p style="color:${d.state===\'ready\'?\'#40e582\':d.state===\'online\'?\'#f5c451\':\'#ff7a87\'}">● ${d.label}</p></article>`).join(\'\');document.querySelectorAll(\'.dogCard\').forEach(c=>c.onclick=()=>toggle(c.dataset.dog));summary()}\n    function toggle(n){if(!dogs[n].online)return;pairMsg=\'\';selected.has(n)?selected.delete(n):selected.add(n);renderCards()}\n    let pairMsg=\'\';\n    function summary(){if(pairMsg){$(\'summary\').textContent=pairMsg;$(\'pairBtn\').disabled=!selected.size;return}$(\'summary\').textContent=selected.size?`${selected.size} dog${selected.size>1?\'s\':\'\'} selected: ${[...selected].join(\', \')}`:\'0 dogs selected\';$(\'pairBtn\').disabled=!selected.size}\n    function renderNav(){$(\'dogNav\').innerHTML=[...selected].map(n=>`<button data-dog="${n}" class="${n===current?\'active\':\'\'}">♙ &nbsp; ${n}</button>`).join(\'\');document.querySelectorAll(\'#dogNav button\').forEach(b=>b.onclick=()=>openDog(b.dataset.dog))}\n    function showPair(){$(\'setup\').style.display=\'none\';$(\'setupNav\').classList.remove(\'active\');$(\'pair\').style.display=\'block\';$(\'dogView\').style.display=\'none\';$(\'pairNav\').classList.add(\'active\');renderCards()}\n    function ensureDogState(n){if(!dogStates[n])dogStates[n]={stopped:false,running:false};if(!histories[n])histories[n]=[]}\n    function openDog(n){ensureDogState(n);current=n;renderNav();$(\'pairNav\').classList.remove(\'active\');$(\'setupNav\').classList.remove(\'active\');$(\'setup\').style.display=\'none\';$(\'pair\').style.display=\'none\';$(\'dogView\').style.display=\'block\';const d=dogs[n];$(\'dogName\').textContent=n;$(\'unit\').textContent=d.unit;$(\'battery\').textContent=(d.battery??\'--\')+\'%\';setProgress(d.progress);renderDogState();showImages();renderHistory()}\n    \n    function renderDogState(){\n     const state=dogStates[current],d=dogs[current];\n     $(\'task\').textContent=state.stopped?\'Emergency stop activated\':state.running?\'Inspection route running\':d.task;\n     $(\'routeBtn\').textContent=state.stopped?\'▶ Send back on inspection route\':state.running?\'■ Route running\':\'▶ Go on your inspection route\';\n     $(\'emergencyStopBtn\').classList.toggle(\'active\',state.stopped);\n     $(\'emergencyStopBtn\').textContent=state.stopped?\'■ Stopped\':\'■ Emergency Stop\';\n     $(\'emergencyStopBtn\').disabled=state.stopped;\n    }\n    function setProgress(p){$(\'percent\').textContent=p+\'% Complete\';const base=$(\'base\'),done=$(\'done\'),mark=$(\'marker\'),len=base.getTotalLength();done.style.strokeDasharray=`${len} ${len}`;done.style.strokeDashoffset=len*(1-p/100);const pt=base.getPointAtLength(len*p/100);mark.setAttribute(\'cx\',pt.x);mark.setAttribute(\'cy\',pt.y)}\n    function renderHistory(){const h=$(\'history\'),items=histories[current];h.innerHTML=items.length?items.map(x=>`<div class="message"><span>${escapeHtml(x)}</span><small>Sent to ${current}</small></div>`).join(\'\'):`<div class="empty">No emergency commands sent to ${current}.</div>`;h.scrollTop=h.scrollHeight}\n    function escapeHtml(s){return s.replace(/[&<>]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\'}[c]))}\n    function send(){const v=$(\'commandInput\').value.trim();if(!v||!current)return;histories[current].push(v);$(\'commandInput\').value=\'\';renderHistory()}\n    function showImages(){$(\'imagesPanel\').classList.remove(\'hidden\');$(\'commandsPanel\').classList.add(\'hidden\');$(\'imagesTab\').classList.add(\'active\');$(\'commandsTab\').classList.remove(\'active\')}\n    $(\'commandsTab\').onclick=()=>{$(\'commandsPanel\').classList.remove(\'hidden\');$(\'imagesPanel\').classList.add(\'hidden\');$(\'commandsTab\').classList.add(\'active\');$(\'imagesTab\').classList.remove(\'active\');renderHistory()};$(\'imagesTab\').onclick=showImages;$(\'send\').onclick=send;$(\'commandInput\').onkeydown=e=>{if(e.key===\'Enter\')send()};$(\'pairNav\').onclick=showPair;$(\'pairBtn\').onclick=pairSelected;$(\'disconnect\').onclick=()=>{selected.delete(current);const next=[...selected][0];current=\'\';renderNav();next?openDog(next):showPair()};$(\'nimBtn\').onclick=nimButton;$(\'routeBtn\').onclick=()=>{if(!current)return;dogStates[current].stopped=false;dogStates[current].running=true;renderDogState()};$(\'emergencyStopBtn\').onclick=()=>{if(!current)return;dogStates[current].stopped=true;dogStates[current].running=false;renderDogState()};\n    \n    \n    /* ---------- Dog Management ---------- */\n    function nextDogUnit(){\n      const used=Object.values(dogs).map(d=>Number(String(d.unit||\'\').replace(/\\D/g,\'\'))).filter(Number.isFinite);\n      const next=(used.length?Math.max(...used):0)+1;\n      return `Unit ${String(next).padStart(2,\'0\')}`;\n    }\n    function openDogModal(){\n      $(\'dogModalBackdrop\').classList.add(\'open\');\n      $(\'dogFormError\').textContent=\'\';\n      renderManagedDogs();\n      setTimeout(()=>$(\'newDogName\').focus(),0);\n    }\n    function closeDogModal(){\n      $(\'dogModalBackdrop\').classList.remove(\'open\');\n      $(\'dogFormError\').textContent=\'\';\n    }\n    function renderManagedDogs(){\n      $(\'managedDogs\').innerHTML=Object.entries(dogs).map(([name,d])=>`<div class="managedDog">\n        <div><b>${escapeHtml(name)}</b><small>${escapeHtml(d.unit||\'\')}</small></div>\n        <div><b>${escapeHtml(d.ip||\'Not set\')}</b><small>IP address</small></div>\n        <div><b>${escapeHtml(d.ssh_user||\'hiwonder\')}</b><small>SSH username</small></div>\n        <div><b>${escapeHtml(String(d.ros_port||9090))}</b><small>ROS port</small></div>\n        <button class="removeDogBtn" type="button" data-remove-dog="${escapeHtml(name)}">Remove</button>\n      </div>`).join(\'\')||\'<div class="empty">No dogs configured.</div>\';\n      document.querySelectorAll(\'[data-remove-dog]\').forEach(button=>button.onclick=()=>removeDog(button.dataset.removeDog));\n    }\n    function resetAddDogForm(){\n      $(\'newDogName\').value=\'\';\n      $(\'newDogIp\').value=\'\';\n      $(\'newDogUser\').value=\'\';\n      $(\'newDogPort\').value=\'9090\';\n      $(\'dogFormError\').textContent=\'\';\n    }\n    async function addDog(){\n      const body={name:$(\'newDogName\').value.trim(),ip:$(\'newDogIp\').value.trim(),\n                  ssh_user:$(\'newDogUser\').value.trim()||\'hiwonder\',ros_port:Number($(\'newDogPort\').value)||9090};\n      if(!body.name||!body.ip){$(\'dogFormError\').textContent=\'Enter at least a name and an IP address.\';return}\n      try{\n        const r=await fetch(\'/api/dogs\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(body)});\n        const data=await r.json();\n        if(!r.ok){$(\'dogFormError\').textContent=data.error||\'Could not add the dog.\';return}\n      }catch(e){$(\'dogFormError\').textContent=\'Could not reach the app server.\';return}\n      resetAddDogForm();\n      await loadDogs();\n      renderManagedDogs();\n    }\n    async function removeDog(name){\n      const d=dogs[name];if(!d)return;\n      if(!confirm(`Remove ${name} (${d.ip}) from the dog list?`))return;\n      try{\n        const r=await fetch(`/api/dogs/${encodeURIComponent(d.id)}`,{method:\'DELETE\'});\n        const data=await r.json();\n        if(!r.ok){$(\'dogFormError\').textContent=data.error||\'Could not remove the dog.\';return}\n      }catch(e){$(\'dogFormError\').textContent=\'Could not reach the app server.\';return}\n      selected.delete(name);delete dogs[name];delete dogStates[name];delete histories[name];\n      if(current===name){current=\'\';const next=[...selected][0];renderNav();next?openDog(next):showPair()}else{renderNav();renderCards()}\n      renderManagedDogs();\n    }\n    $(\'manageDogsBtn\').onclick=openDogModal;\n    $(\'closeDogModal\').onclick=closeDogModal;\n    $(\'cancelAddDog\').onclick=()=>{resetAddDogForm();closeDogModal()};\n    $(\'addDogBtn\').onclick=addDog;\n    $(\'addDogForm\').onsubmit=e=>{e.preventDefault();addDog()};\n    $(\'dogModalBackdrop\').onclick=e=>{if(e.target===$(\'dogModalBackdrop\'))closeDogModal()};\n    document.addEventListener(\'keydown\',e=>{if(e.key===\'Escape\'&&$(\'dogModalBackdrop\').classList.contains(\'open\'))closeDogModal()});\n\n    /* ---------- Route Setup (placeholder data; swap for /api/routes calls later) ---------- */\n    let rsRoutes={\'Loading routes...\':[]};   // filled from /api/routes by rsLoadRoutes()\n    const rsRouteFiles={};                       // route name -> file in routes/, for saving later\n    async function rsLoadRoutes(){\n     try{\n      const r=await fetch(\'/api/routes\');const data=await r.json();\n      const loaded={};\n      data.routes.filter(x=>!x.error).forEach(x=>{loaded[x.name]=x.waypoints;rsRouteFiles[x.name]=x.file});\n      if(Object.keys(loaded).length){\n       rsRoutes=loaded;\n       rsRoute=Object.keys(loaded).find(n=>rsRouteFiles[n]===\'data_center.json\')||Object.keys(loaded)[0];\n      }\n     }catch(e){rsSay(\'Could not load routes from the server\',true)}\n     rsSel=-1;rsView=null;\n     if($(\'setup\').style.display===\'block\')rsRender();\n    }\n    let rsDogNames=Object.keys(dogs).filter(n=>dogs[n].online);\n    const rsPoses=Object.fromEntries(rsDogNames.map((n,i)=>[n,{x:3.64-i*.8,y:1.72+i*.4,yaw:0.5}]));\n    let rsDog=rsDogNames[0],rsRoute=\'Loading routes...\',rsSel=-1,rsView=null;\n    const rsDeg=r=>Math.round(r*180/Math.PI)+\'°\';\n    function rsEsc(s){return String(s).replace(/[&<>"]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\'}[c]))}\n    function rsSay(t,err){$(\'rsMsg\').textContent=t;$(\'rsMsg\').className=\'rsMsg\'+(err?\' err\':\'\')}\n    \n    function showSetup(){rsDogNames=Object.keys(dogs);  // all configured dogs; offline ones show as offline\n     rsDog=rsDogNames.includes(rsDog)?rsDog:rsDogNames[0];rsDogNames.forEach((n,i)=>{if(!rsPoses[n])rsPoses[n]={x:3.64-i*.8,y:1.72+i*.4,yaw:0.5}});current=\'\';renderNav();$(\'pair\').style.display=\'none\';$(\'dogView\').style.display=\'none\';$(\'setup\').style.display=\'block\';$(\'pairNav\').classList.remove(\'active\');$(\'setupNav\').classList.add(\'active\');rsRender()}\n    function rsRender(){\n     $(\'rsDogs\').innerHTML=rsDogNames.map(n=>`<button type="button" data-dog="${n}" aria-pressed="${n===rsDog}">${n}</button>`).join(\'\');\n     document.querySelectorAll(\'#rsDogs button\').forEach(b=>b.onclick=()=>{rsDog=b.dataset.dog;rsView=null;rsRender()});\n     $(\'rsRoute\').innerHTML=Object.keys(rsRoutes).map(r=>`<option${r===rsRoute?\' selected\':\'\'}>${rsEsc(r)}</option>`).join(\'\');\n     $(\'rsBadgeText\').textContent=!rsDog?\'No dogs configured\':dogs[rsDog]&&dogs[rsDog].state===\'ready\'?`${rsDog} connected`:`${rsDog} offline`;\n     rsTable();rsPose();rsDraw();\n    }\n    function rsTable(){\n     const w=rsRoutes[rsRoute];\n     $(\'rsListTitle\').textContent=`Waypoints · ${rsRoute}`;\n     $(\'rsCount\').textContent=`${w.length} stop${w.length===1?\'\':\'s\'} · saved automatically`;\n     $(\'rsBody\').innerHTML=w.length?w.map((p,i)=>`<tr class="${i===rsSel?\'sel\':\'\'}" data-i="${i}">\n    <td><span class="rsNum ${p.photo?\'\':\'plain\'}">${i+1}</span></td>\n    <td><input class="rsName" value="${rsEsc(p.name)}" data-i="${i}" aria-label="Name of stop ${i+1}"></td>\n    <td class="rsMono">${p.x.toFixed(2)}, ${p.y.toFixed(2)}</td>\n    <td class="rsMono">${rsDeg(p.yaw)}</td>\n    <td><button type="button" class="rsTag ${p.photo?\'photo\':\'nophoto\'}" data-act="photo" data-i="${i}" aria-pressed="${p.photo}">${p.photo?\'Photo\':\'No photo\'}</button></td>\n    <td><button type="button" class="rsTag ${p.required?\'req\':\'opt\'}" data-act="req" data-i="${i}" aria-pressed="${p.required}">${p.required?\'Required\':\'Optional\'}</button></td>\n    <td class="rsActs"><button type="button" class="rsIcon" data-act="up" data-i="${i}" aria-label="Move ${rsEsc(p.name)} up"${i===0?\' disabled\':\'\'}>↑</button> <button type="button" class="rsIcon" data-act="down" data-i="${i}" aria-label="Move ${rsEsc(p.name)} down"${i===w.length-1?\' disabled\':\'\'}>↓</button> <button type="button" class="rsDel" data-act="del" data-i="${i}" aria-label="Delete ${rsEsc(p.name)}">Delete</button></td>\n    </tr>`).join(\'\'):`<tr><td colspan="7" class="rsEmpty">No stops yet. Drive the dog to its start spot, name it "Start", and press Record.</td></tr>`;\n    }\n    function rsPose(){const p=rsPoses[rsDog]||{x:0,y:0,yaw:0};$(\'rsX\').innerHTML=`${p.x.toFixed(2)}<span>m</span>`;$(\'rsY\').innerHTML=`${p.y.toFixed(2)}<span>m</span>`;$(\'rsYaw\').textContent=rsDeg(p.yaw)}\n    function rsDraw(){\n     const w=rsRoutes[rsRoute],p=rsPoses[rsDog]||{x:0,y:0,yaw:0},W=640,H=340,m=46;\n     const pts=w.map(q=>[q.x,q.y]).concat([[p.x,p.y]]);\n     const fits=v=>pts.every(([x,y])=>x>v.x0+.3&&x<v.x1-.3&&y>v.y0+.3&&y<v.y1-.3);\n     if(!rsView||!fits(rsView)){const xs=pts.map(q=>q[0]),ys=pts.map(q=>q[1]);rsView={x0:Math.min(...xs)-1,x1:Math.max(...xs)+1,y0:Math.min(...ys)-1,y1:Math.max(...ys)+1}}\n     const v=rsView,s=Math.min((W-2*m)/(v.x1-v.x0),(H-2*m)/(v.y1-v.y0)),ox=(W-s*(v.x1-v.x0))/2,oy=(H-s*(v.y1-v.y0))/2;\n     const X=x=>ox+(x-v.x0)*s,Y=y=>H-(oy+(y-v.y0)*s);\n     let g=\'\';\n     for(let x=Math.ceil(v.x0);x<=v.x1;x++)g+=`<line x1="${X(x)}" y1="0" x2="${X(x)}" y2="${H}" stroke="#122438"/><text x="${X(x)+4}" y="${H-8}" fill="#4c6580" font-family="Consolas,monospace" font-size="11">${x}m</text>`;\n     for(let y=Math.ceil(v.y0);y<=v.y1;y++)g+=`<line x1="0" y1="${Y(y)}" x2="${W}" y2="${Y(y)}" stroke="#122438"/>`;\n     if(w.length>1)g+=`<polyline points="${w.map(q=>X(q.x)+\',\'+Y(q.y)).join(\' \')}" fill="none" stroke="#2f8cff" stroke-opacity=".6" stroke-width="2" stroke-dasharray="3 7" stroke-linecap="round"/>`;\n     const seen=new Set();let shown=0;\n     w.forEach((q,i)=>{const key=q.x.toFixed(2)+\',\'+q.y.toFixed(2);if(seen.has(key)&&i!==rsSel)return;seen.add(key);  // return-leg stops share a spot: draw it once\n      const below=(shown++%2===0),x=X(q.x),y=Y(q.y),c=q.photo?\'#2f8cff\':\'#3a5470\';\n      g+=`<line x1="${x}" y1="${y}" x2="${x+Math.cos(q.yaw)*22}" y2="${y-Math.sin(q.yaw)*22}" stroke="${c}" stroke-width="2" stroke-linecap="round"/>`;\n      if(i===rsSel)g+=`<circle cx="${x}" cy="${y}" r="20" fill="#2f8cff" fill-opacity=".18"/>`;\n      g+=`<circle cx="${x}" cy="${y}" r="13" fill="${c}" stroke="#071421" stroke-width="2"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="#fff" font-family="Consolas,monospace" font-size="12" font-weight="600">${i+1}</text><text x="${x}" y="${below?y+30:y-20}" text-anchor="middle" fill="#dbe7f4" font-size="12.5" font-weight="600">${rsEsc(q.name)}</text>`});\n     const dx=X(p.x),dy=Y(p.y);\n     g+=`<circle cx="${dx}" cy="${dy}" r="24" fill="none" stroke="#35e08a" stroke-opacity=".25" stroke-width="2"/><g transform="translate(${dx} ${dy}) rotate(${-p.yaw*180/Math.PI})"><path d="M17 0 L-9 10 L-4 0 L-9 -10 Z" fill="#35e08a"/></g>`;\n     $(\'rsMap\').innerHTML=g;\n    }\n    function rsRecord(){\n     const w=rsRoutes[rsRoute],p=rsPoses[rsDog];\n     const name=$(\'rsWpName\').value.trim()||`Checkpoint${w.length+1}`;\n     if(w.some(q=>q.name===name)){rsSay(`There\'s already a stop called "${name}"`,true);return}\n     w.push({name,x:+p.x.toFixed(2),y:+p.y.toFixed(2),yaw:+p.yaw.toFixed(2),photo:$(\'rsPhoto\').checked,required:$(\'rsRequired\').checked});\n     rsSel=w.length-1;$(\'rsWpName\').value=\'\';rsSay(`Saved ${name} at ${p.x.toFixed(2)}, ${p.y.toFixed(2)}`);rsTable();rsDraw();\n    }\n    \n    $(\'setupNav\').onclick=showSetup;\n    $(\'rsRecord\').onclick=rsRecord;\n    $(\'rsWpName\').onkeydown=e=>{if(e.key===\'Enter\')rsRecord()};\n    $(\'rsRoute\').onchange=e=>{rsRoute=e.target.value;rsSel=-1;rsView=null;rsTable();rsDraw()};\n    $(\'rsRecenter\').onclick=()=>{rsView=null;rsDraw()};\n    $(\'rsNewToggle\').onclick=()=>{const f=$(\'rsNewForm\');f.classList.toggle(\'hidden\');$(\'rsNewToggle\').setAttribute(\'aria-expanded\',!f.classList.contains(\'hidden\'));if(!f.classList.contains(\'hidden\'))$(\'rsNewName\').focus()};\n    $(\'rsNewForm\').onsubmit=e=>{e.preventDefault();const n=$(\'rsNewName\').value.trim();if(!n){rsSay(\'Type a name for the new route first\',true);return}if(rsRoutes[n]){rsSay(`A route called "${n}" already exists`,true);return}rsRoutes[n]=[];rsRoute=n;rsSel=-1;rsView=null;$(\'rsNewName\').value=\'\';$(\'rsNewForm\').classList.add(\'hidden\');$(\'rsNewToggle\').setAttribute(\'aria-expanded\',\'false\');rsSay(`Created ${n}. Record its first stop.`);rsRender();$(\'rsWpName\').focus()};\n    $(\'rsBody\').onclick=e=>{const b=e.target.closest(\'button\'),tr=e.target.closest(\'tr[data-i]\');if(!tr)return;const w=rsRoutes[rsRoute],i=+tr.dataset.i;\n     if(!b){rsSel=i;document.querySelectorAll(\'#rsBody tr\').forEach(r=>r.classList.toggle(\'sel\',+r.dataset.i===i));rsDraw();return}\n     const a=b.dataset.act;\n     if(a===\'photo\')w[i].photo=!w[i].photo;\n     if(a===\'req\')w[i].required=!w[i].required;\n     if(a===\'up\'&&i>0){[w[i-1],w[i]]=[w[i],w[i-1]];rsSel=i-1}\n     if(a===\'down\'&&i<w.length-1){[w[i+1],w[i]]=[w[i],w[i+1]];rsSel=i+1}\n     if(a===\'del\'){const n=w[i].name;w.splice(i,1);rsSel=-1;rsSay(`Deleted ${n}`)}\n     rsTable();rsDraw()};\n    $(\'rsBody\').onchange=e=>{if(!e.target.classList.contains(\'rsName\'))return;const w=rsRoutes[rsRoute],i=+e.target.dataset.i,n=e.target.value.trim();\n     if(!n||w.some((q,j)=>j!==i&&q.name===n)){rsSay(n?`There\'s already a stop called "${n}"`:"Name can\'t be empty",true);rsTable();return}\n     w[i].name=n;rsSay(\'Renamed\');rsDraw()};\n    $(\'rsBody\').onkeydown=e=>{if(e.key===\'Enter\'&&e.target.classList.contains(\'rsName\'))e.target.blur()};\n    \n    selected.clear();current=\'\';renderNav();showPair();\n    rsLoadRoutes();\n\n    /* ---------- Live status from the backend ---------- */\n    async function loadDogs(){\n     try{\n      const data=await (await fetch(\'/api/dogs\')).json();\n      const names=new Set(data.dogs.map(x=>x.name));\n      Object.keys(dogs).forEach(n=>{if(!names.has(n)&&!dogs[n].preparing){delete dogs[n];selected.delete(n)}});\n      data.dogs.forEach(x=>{\n       if(dogs[x.name]&&dogs[x.name].preparing)return;   // Pair & Connect is updating this card\n       dogs[x.name]=Object.assign(dogs[x.name]||{progress:0,task:\'Not on patrol\'},\n         {id:x.id,unit:x.unit,ip:x.ip,ssh_user:x.ssh_user,ros_port:x.ros_port,online:x.online,state:x.state,label:x.label,battery:x.battery});\n       ensureDogState(x.name);\n       if(!x.online&&selected.has(x.name)&&!dogStates[x.name].running)selected.delete(x.name);\n      });\n     }catch(e){/* server unreachable: keep last known state */}\n     if($(\'pair\').style.display!==\'none\')renderCards();\n    }\n    async function loadNim(){\n     let n={up:false,loaded:false,label:\'Could not reach the app server\'};\n     try{n=await (await fetch(\'/api/nim\')).json()}catch(e){}\n     nimOn=!!n.loaded;\n     $(\'nimText\').textContent=nimOn?\'READY\':n.up?\'NOT LOADED\':\'OFF\';\n     $(\'nimDetail\').textContent=n.label+(n.model?` · ${n.model}`:\'\');\n     $(\'nimDot\').style.background=nimOn?\'var(--green)\':\'var(--red)\';\n     $(\'nimDot\').style.boxShadow=nimOn?\'0 0 10px #31df7966\':\'0 0 10px #ff657466\';\n     if(nimStarting&&!nimOn&&Date.now()<nimStarting){$(\'nimText\').textContent=\'STARTING\';$(\'nimBtn\').textContent=\'Starting…\';$(\'nimBtn\').disabled=true}\n     else{nimStarting=0;$(\'nimBtn\').disabled=false;$(\'nimBtn\').textContent=nimOn?\'Stop Qwen\':n.up?\'Check again\':\'Start Qwen\'}\n    }\n    let nimStarting=0;\n    async function nimButton(){\n     const label=$(\'nimBtn\').textContent;\n     if(label===\'Check again\'){loadNim();return}\n     const action=label===\'Stop Qwen\'?\'stop\':\'start\';\n     if(action===\'stop\'&&!confirm(\'Stop the AI model? Photo analysis will be unavailable until it is started again.\'))return;\n     try{\n      const r=await fetch(\'/api/nim/\'+action,{method:\'POST\'});const data=await r.json();\n      if(!r.ok){$(\'nimDetail\').textContent=data.error||\'Could not \'+action+\' the AI model\';return}\n     }catch(e){$(\'nimDetail\').textContent=\'Could not reach the app server\';return}\n     if(action===\'start\'){nimStarting=Date.now()+5*60*1000;$(\'nimDetail\').textContent=\'Loading the model, this takes a minute or two…\'}\n     loadNim();setTimeout(loadNim,4000);\n    }\n\n    /* Pair & Connect: put each selected dog in patrol mode over SSH, then open it */\n    async function prepareDog(name){\n     const d=dogs[name];\n     if(d.state===\'ready\')return true;\n     d.preparing=true;d.state=\'online\';d.label=\'Starting…\';renderCards();\n     let ok=false;\n     try{\n      const resp=await fetch(`/api/dogs/${encodeURIComponent(d.id)}/prepare`,{method:\'POST\'});\n      const reader=resp.body.getReader(),dec=new TextDecoder();let buf=\'\';\n      while(true){\n       const {done,value}=await reader.read();if(done)break;\n       buf+=dec.decode(value,{stream:true});const lines=buf.split(\'\\n\');buf=lines.pop();\n       for(const line of lines){\n        if(!line.startsWith(\'data: \'))continue;\n        const u=JSON.parse(line.slice(6));\n        if(u.done){ok=u.ok;d.label=u.ok?\'Ready for patrol\':\'✗ \'+u.msg;d.state=u.ok?\'ready\':\'error\'}\n        else d.label=`Step ${u.step}/${u.total} · ${u.msg}`;\n        renderCards();\n       }\n      }\n     }catch(e){d.label=\'✗ Could not reach the app server\';d.state=\'error\'}\n     d.preparing=false;renderCards();\n     return ok;\n    }\n    async function pairSelected(){\n     const names=[...selected];if(!names.length)return;\n     $(\'pairBtn\').disabled=true;pairMsg=`Connecting ${names.join(\', \')}…`;$(\'summary\').textContent=pairMsg;\n     const results=await Promise.all(names.map(prepareDog));\n     const failed=names.filter((n,i)=>!results[i]);\n     failed.forEach(n=>selected.delete(n));\n     pairMsg=\'\';\n     if(failed.length){\n      pairMsg=`Couldn\'t connect ${failed.join(\', \')}. See the card for why.`+(selected.size?\' The others are ready.\':\'\');\n      renderCards();\n      if(!selected.size)return;\n     }\n     renderNav();openDog([...selected][0]);\n    }\n    loadDogs();loadNim();\n    setInterval(loadDogs,5000);setInterval(loadNim,15000);\n    </script></body></html>', 'startup/dog_prep.py': '"""Dog list (dogs.json) and "get this dog ready to patrol" over SSH.\n\nThe Pair & Connect button runs prepare_dog(), which does over SSH exactly what\nwe used to type by hand after `ssh hiwonder@<ip>`:\n\n    1. stop pug_bringup.service        (the dog\'s normal app mode)\n    2. kill leftover ROS processes     (prevents "launched twice")\n    3. set the dog\'s clock             (it resets to 2023 after a reboot)\n    4. start patrol.launch             (navigation + rosbridge, saved map)\n    5. wait until patrol mode answers  (rosbridge port + move_base/amcl nodes)\n\nOne-time setup on each dog (on site), so this runs without typing passwords:\n    ssh-copy-id hiwonder@<DOG_IP>\n    echo \'hiwonder ALL=(ALL) NOPASSWD: /bin/systemctl, /bin/date\' | \\\n        ssh -t hiwonder@<DOG_IP> \'sudo tee /etc/sudoers.d/pawpatrol && sudo chmod 440 /etc/sudoers.d/pawpatrol\'\n"""\n\nimport json\nimport os\nimport shlex\nimport socket\nimport subprocess\nimport threading\nimport time\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nDOGS_FILE = os.path.join(ROOT, "dogs.json")\n\nDEFAULT_DOGS = [\n    {"id": "dog1", "name": "Pumbaa", "ip": "192.168.0.60", "ssh_user": "hiwonder", "ros_port": 9090},\n    {"id": "dog2", "name": "Timon", "ip": "192.168.0.85", "ssh_user": "hiwonder", "ros_port": 9090},\n]\n\nMAP_NAME = "datacenter_01"\n\n# Runs in the dog\'s own login shell (zsh on our dogs) so the ROS setup and the\n# Hiwonder LIDAR/CAMERA variables from its startup files are loaded, exactly\n# like a terminal you SSH\'d into. setsid + nohup keep it running after SSH exits.\nPATROL_LAUNCH = (f"setsid nohup roslaunch pug_navigation patrol.launch map:={MAP_NAME} "\n                 f"> ~/patrol.log 2>&1 < /dev/null &")\n\n_lock = threading.Lock()\n\n\n# ---------------------------------------------------------------- dog list --\n\ndef load_dogs():\n    """Dogs from dogs.json (created with Pumbaa and Timon the first time)."""\n    with _lock:\n        if not os.path.exists(DOGS_FILE):\n            _write(DEFAULT_DOGS)\n        with open(DOGS_FILE) as f:\n            return json.load(f)\n\n\ndef _write(dogs):\n    with open(DOGS_FILE, "w") as f:\n        json.dump(dogs, f, indent=4)\n\n\ndef add_dog(name, ip, ssh_user="hiwonder", ros_port=9090):\n    """Add a dog. Returns (dog, error)."""\n    name, ip, ssh_user = name.strip(), ip.strip(), (ssh_user or "hiwonder").strip()\n    parts = ip.split(".")\n    if not name or not ip:\n        return None, "Name and IP address are required"\n    if len(parts) != 4 or not all(p.isdigit() and 0 <= int(p) <= 255 for p in parts):\n        return None, "Enter a valid IPv4 address, e.g. 192.168.0.60"\n    try:\n        ros_port = int(ros_port)\n        assert 1 <= ros_port <= 65535\n    except (ValueError, AssertionError):\n        return None, "ROS port must be a number between 1 and 65535"\n    dogs = load_dogs()\n    if any(d["name"].lower() == name.lower() for d in dogs):\n        return None, f"A dog called {name} already exists"\n    if any(d["ip"] == ip for d in dogs):\n        return None, f"{ip} is already assigned to another dog"\n    used = {d["id"] for d in dogs}\n    n = 1\n    while f"dog{n}" in used:\n        n += 1\n    dog = {"id": f"dog{n}", "name": name, "ip": ip, "ssh_user": ssh_user, "ros_port": ros_port}\n    with _lock:\n        _write(dogs + [dog])\n    return dog, None\n\n\ndef remove_dog(dog_id):\n    dogs = load_dogs()\n    keep = [d for d in dogs if d["id"] != dog_id]\n    if len(keep) == len(dogs):\n        return False\n    with _lock:\n        _write(keep)\n    return True\n\n\n# ------------------------------------------------------------ status checks --\n\ndef port_open(ip, port, timeout=0.6):\n    """True if something is listening on ip:port (quick TCP connect)."""\n    try:\n        with socket.create_connection((ip, port), timeout=timeout):\n            return True\n    except OSError:\n        return False\n\n\ndef dog_status(dog):\n    """offline / online (on, patrol mode not started) / ready (patrol mode up)."""\n    if port_open(dog["ip"], dog.get("ros_port", 9090)):\n        return "ready", "Ready for patrol"\n    if port_open(dog["ip"], 22):\n        return "online", "On · press Pair & Connect to start patrol mode"\n    return "offline", "Offline · check the dog is on and on the TP-Link WiFi"\n\n\n# ----------------------------------------------------------------- ssh prep --\n\ndef _ssh(dog, command, timeout=30):\n    """Run a command on the dog in its login shell. Returns (ok, output)."""\n    target = f"{dog.get(\'ssh_user\', \'hiwonder\')}@{dog[\'ip\']}"\n    remote = "exec $SHELL -lic " + shlex.quote(command)\n    try:\n        r = subprocess.run(\n            ["ssh", "-o", "BatchMode=yes", "-o", "ConnectTimeout=5",\n             "-o", "StrictHostKeyChecking=accept-new", target, remote],\n            capture_output=True, text=True, timeout=timeout)\n    except subprocess.TimeoutExpired:\n        return False, "timed out"\n    except FileNotFoundError:\n        return False, "ssh is not installed on this computer"\n    out = (r.stdout + r.stderr).strip()\n    return r.returncode == 0, out\n\n\ndef _explain(out):\n    """Turn a raw SSH/sudo error into something an operator can act on."""\n    low = out.lower()\n    if "permission denied" in low or "publickey" in low:\n        return "SSH key not set up for this dog (one-time: ssh-copy-id hiwonder@<ip>)"\n    if "a password is required" in low or "sudo:" in low:\n        return "The dog asked for a sudo password (one-time sudoers setup needed)"\n    if "no route to host" in low or "timed out" in low or "unreachable" in low:\n        return "Can\'t reach the dog: is it on and on the TP-Link WiFi?"\n    if "connection refused" in low:\n        return "The dog refused SSH: is it still booting?"\n    return out.splitlines()[-1][:160] if out else "Unknown error"\n\n\ndef prepare_dog(dog, ready_timeout=90):\n    """Get a dog into patrol mode. Yields progress dicts for the UI:\n        {"step": 1-5, "total": 5, "status": "running"|"ok"|"fail", "msg": "..."}\n    The last item is {"done": True, "ok": bool, "msg": "..."}.\n    """\n    total = 5\n\n    def step(n, status, msg):\n        return {"step": n, "total": total, "status": status, "msg": msg}\n\n    if port_open(dog["ip"], dog.get("ros_port", 9090)):\n        yield {"done": True, "ok": True, "msg": "Already in patrol mode"}\n        return\n\n    yield step(1, "running", "Connecting and stopping the dog\'s app mode...")\n    ok, out = _ssh(dog, "sudo -n systemctl stop pug_bringup.service")\n    if not ok:\n        yield step(1, "fail", _explain(out))\n        yield {"done": True, "ok": False, "msg": _explain(out)}\n        return\n    yield step(1, "ok", "App mode stopped")\n\n    yield step(2, "running", "Clearing leftover ROS processes...")\n    _ssh(dog, "pkill -f roslaunch; pkill -f rosmaster; sleep 4; true")\n    yield step(2, "ok", "Cleared")\n\n    yield step(3, "running", "Setting the dog\'s clock...")\n    ok, out = _ssh(dog, f"sudo -n date -s @{int(time.time())}")\n    yield step(3, "ok" if ok else "fail", "Clock set" if ok else\n               f"Couldn\'t set the clock ({_explain(out)}); continuing")\n\n    yield step(4, "running", "Starting patrol mode (map, navigation, rosbridge)...")\n    ok, out = _ssh(dog, PATROL_LAUNCH)\n    if not ok:\n        yield step(4, "fail", _explain(out))\n        yield {"done": True, "ok": False, "msg": _explain(out)}\n        return\n    yield step(4, "ok", "Patrol mode launched")\n\n    yield step(5, "running", "Waiting for navigation and rosbridge to come up...")\n    deadline = time.time() + ready_timeout\n    while time.time() < deadline:\n        if port_open(dog["ip"], dog.get("ros_port", 9090)):\n            ok, out = _ssh(dog, "rosnode list")\n            missing = [n for n in ("/move_base_node", "/amcl") if n not in out]\n            if ok and not missing:\n                yield step(5, "ok", "Navigation and rosbridge are up")\n                yield {"done": True, "ok": True, "msg": "Ready for patrol"}\n                return\n        time.sleep(3)\n\n    _, log = _ssh(dog, "tail -5 ~/patrol.log")\n    msg = "Patrol mode didn\'t come up in time"\n    if "same name" in log:\n        msg += " (launched twice; press Pair & Connect again)"\n    elif "lidar" in log.lower():\n        msg += " (LiDAR problem; power-cycle the dog)"\n    yield step(5, "fail", msg)\n    yield {"done": True, "ok": False, "msg": msg}\n'}
KNOWN_APP = ['fb9e801180035b559061dd2cdadb82c9d107c88a549339c9c51e7e944b4cc922', '900b4a067ec5f99eee567db1c18b9bedc104b23b13581fc580adedc7a6725b1f']
KNOWN_NIM = ['b456a69dc9cd240b61820049bb792102718e62bcdcb21e9dbf6d62877fc34bd3']

if not os.path.exists("app.py"):
    sys.exit("Run this from the RoboticDogs folder (where app.py is).")
branch = subprocess.run(["git", "branch", "--show-current"], capture_output=True, text=True).stdout.strip()
if branch != "new-ui":
    sys.exit(f"You're on branch '{branch}'. Switch first:  git checkout new-ui")

def sha(path):
    return hashlib.sha256(open(path).read().encode()).hexdigest() if os.path.exists(path) else None

if sha("app.py") not in KNOWN_APP + [hashlib.sha256(FILES["app.py"].encode()).hexdigest()]:
    sys.exit("app.py has changes this script doesn't know about (maybe a teammate's). "
             "Nothing was changed. Run 'git pull', and if it still fails, ask Claude to merge by hand.")
if sha("nim_config.py") not in KNOWN_NIM + [hashlib.sha256(FILES["nim_config.py"].encode()).hexdigest()]:
    sys.exit("nim_config.py has unexpected changes. Nothing was changed.")

for path, content in FILES.items():
    if os.path.exists(path):
        old = open(path).read()
        if old == content:
            print("unchanged", path); continue
        open(path + ".bak", "w").write(old)
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    open(path, "w").write(content)
    print("wrote    ", path)
print("\nDone. Start the app and open http://localhost:5000/new")